begin;
-- Story Sequencing verse reading (22 Nov 2026).
--   * questions.clue_refs now also holds, for sequence questions, the KJV passage(s) behind each event,
--     in the correct order: [[{ref, text}, ...], ...]. Still not exposed by published_questions.
--   * submit_sequence returns clue_refs after the answer, next to correct_order.
create or replace function public.submit_sequence(p_session uuid, p_question text, p_order jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_q public.questions; v_correct boolean; v_res jsonb;
begin
  select * into v_q from public.questions where id = p_question and status = 'published' and game_mode = 'sequence';
  if v_q.id is null then raise exception 'question_not_found'; end if;
  v_correct := (p_order = v_q.options);
  v_res := public._record_answer(p_session, p_question, v_correct, -1, 100);
  return v_res || jsonb_build_object('correct', v_correct, 'correct_order', v_q.options,
    'explanation', v_q.explanation, 'reference', v_q.reference_label, 'verse_text', v_q.verse_text,
    'clue_refs', v_q.clue_refs,
    'points', case when v_correct then 100 else 0 end);
end $$;

update public.questions set clue_refs = '[[{"ref": "Genesis 12:1", "text": "Now the LORD had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father’s house, unto a land that I will shew thee:"}], [{"ref": "Genesis 15:5", "text": "And he brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be."}], [{"ref": "Genesis 17:5", "text": "Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee."}], [{"ref": "Genesis 21:2-3", "text": "For Sarah conceived, and bare Abraham a son in his old age, at the set time of which God had spoken to him. And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac."}], [{"ref": "Genesis 22:1-2", "text": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}]]'::jsonb, updated_at = now() where id = 'seq-abraham' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 15:2-6", "text": "And Absalom rose up early, and stood beside the way of the gate: and it was so, that when any man that had a controversy came to the king for judgment, then Absalom called unto him, and said, Of what city art thou? And he said, Thy servant is of one of the tribes of Israel. And Absalom said unto him, See, thy matters are good and right; but there is no man deputed of the king to hear thee. Absalom said moreover, Oh that I were made judge in the land, that every man which hath any suit or cause might come unto me, and I would do him justice! And it was so, that when any man came nigh to him to do him obeisance, he put forth his hand, and took him, and kissed him. And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel."}], [{"ref": "2 Samuel 15:14-16", "text": "And David said unto all his servants that were with him at Jerusalem, Arise, and let us flee; for we shall not else escape from Absalom: make speed to depart, lest he overtake us suddenly, and bring evil upon us, and smite the city with the edge of the sword. And the king’s servants said unto the king, Behold, thy servants are ready to do whatsoever my lord the king shall appoint. And the king went forth, and all his household after him. And the king left ten women, which were concubines, to keep the house."}], [{"ref": "2 Samuel 18:9", "text": "And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away."}], [{"ref": "2 Samuel 18:14", "text": "Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak."}], [{"ref": "2 Samuel 18:33", "text": "And the king was much moved, and went up to the chamber over the gate, and wept: and as he went, thus he said, O my son Absalom, my son, my son Absalom! would God I had died for thee, O Absalom, my son, my son!"}]]'::jsonb, updated_at = now() where id = 'seq-absalom' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 11:1", "text": "And the whole earth was of one language, and of one speech."}], [{"ref": "Genesis 11:2", "text": "And it came to pass, as they journeyed from the east, that they found a plain in the land of Shinar; and they dwelt there."}], [{"ref": "Genesis 11:3-4", "text": "And they said one to another, Go to, let us make brick, and burn them throughly. And they had brick for stone, and slime had they for morter. And they said, Go to, let us build us a city and a tower, whose top may reach unto heaven; and let us make us a name, lest we be scattered abroad upon the face of the whole earth."}], [{"ref": "Genesis 11:5", "text": "And the LORD came down to see the city and the tower, which the children of men builded."}], [{"ref": "Genesis 11:7-9", "text": "Go to, let us go down, and there confound their language, that they may not understand one another’s speech. So the LORD scattered them abroad from thence upon the face of all the earth: and they left off to build the city. Therefore is the name of it called Babel; because the LORD did there confound the language of all the earth: and from thence did the LORD scatter them abroad upon the face of all the earth."}]]'::jsonb, updated_at = now() where id = 'seq-babel' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Numbers 22:21", "text": "And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab."}], [{"ref": "Numbers 22:23", "text": "And the ass saw the angel of the LORD standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way."}], [{"ref": "Numbers 22:28", "text": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}], [{"ref": "Numbers 22:31", "text": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}], [{"ref": "Numbers 23:11", "text": "And Balak said unto Balaam, What hast thou done unto me? I took thee to curse mine enemies, and, behold, thou hast blessed them altogether."}]]'::jsonb, updated_at = now() where id = 'seq-balaam' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:3-4", "text": "And in process of time it came to pass, that Cain brought of the fruit of the ground an offering unto the LORD. And Abel, he also brought of the firstlings of his flock and of the fat thereof. And the LORD had respect unto Abel and to his offering:"}], [{"ref": "Genesis 4:6-7", "text": "And the LORD said unto Cain, Why art thou wroth? and why is thy countenance fallen? If thou doest well, shalt thou not be accepted? and if thou doest not well, sin lieth at the door. And unto thee shall be his desire, and thou shalt rule over him."}], [{"ref": "Genesis 4:8", "text": "And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him."}], [{"ref": "Genesis 4:15", "text": "And the LORD said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the LORD set a mark upon Cain, lest any finding him should kill him."}]]'::jsonb, updated_at = now() where id = 'seq-cain_abel' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 1:9", "text": "And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight."}], [{"ref": "Acts 2:1-4", "text": "And when the day of Pentecost was fully come, they were all with one accord in one place. And suddenly there came a sound from heaven as of a rushing mighty wind, and it filled all the house where they were sitting. And there appeared unto them cloven tongues like as of fire, and it sat upon each of them. And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance."}], [{"ref": "Acts 3:2-8", "text": "And a certain man lame from his mother’s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms of them that entered into the temple; Who seeing Peter and John about to go into the temple asked an alms. And Peter, fastening his eyes upon him with John, said, Look on us. And he gave heed unto them, expecting to receive something of them. Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk. And he took him by the right hand, and lifted him up: and immediately his feet and ankle bones received strength. And he leaping up stood, and walked, and entered with them into the temple, walking, and leaping, and praising God."}], [{"ref": "Acts 7:59", "text": "And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit."}], [{"ref": "Acts 9:3-5", "text": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks."}]]'::jsonb, updated_at = now() where id = 'seq-church' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 1:3-5", "text": "And God said, Let there be light: and there was light. And God saw the light, that it was good: and God divided the light from the darkness. And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day."}], [{"ref": "Genesis 1:6-8", "text": "And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters. And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so. And God called the firmament Heaven. And the evening and the morning were the second day."}], [{"ref": "Genesis 1:9-13", "text": "And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so. And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good. And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so. And the earth brought forth grass, and herb yielding seed after his kind, and the tree yielding fruit, whose seed was in itself, after his kind: and God saw that it was good. And the evening and the morning were the third day."}], [{"ref": "Genesis 1:14-19", "text": "And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years: And let them be for lights in the firmament of the heaven to give light upon the earth: and it was so. And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also. And God set them in the firmament of the heaven to give light upon the earth, And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good. And the evening and the morning were the fourth day."}], [{"ref": "Genesis 1:20-23", "text": "And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl that may fly above the earth in the open firmament of heaven. And God created great whales, and every living creature that moveth, which the waters brought forth abundantly, after their kind, and every winged fowl after his kind: and God saw that it was good. And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth. And the evening and the morning were the fifth day."}]]'::jsonb, updated_at = now() where id = 'seq-creation' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Daniel 1:8", "text": "But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."}], [{"ref": "Daniel 2:31-32", "text": "Thou, O king, sawest, and behold a great image. This great image, whose brightness was excellent, stood before thee; and the form thereof was terrible. This image’s head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"}, {"ref": "Daniel 2:36-38", "text": "This is the dream; and we will tell the interpretation thereof before the king. Thou, O king, art a king of kings: for the God of heaven hath given thee a kingdom, power, and strength, and glory. And wheresoever the children of men dwell, the beasts of the field and the fowls of the heaven hath he given into thine hand, and hath made thee ruler over them all. Thou art this head of gold."}], [{"ref": "Daniel 3:20-23", "text": "And he commanded the most mighty men that were in his army to bind Shadrach, Meshach, and Abed-nego, and to cast them into the burning fiery furnace. Then these men were bound in their coats, their hosen, and their hats, and their other garments, and were cast into the midst of the burning fiery furnace. Therefore because the king’s commandment was urgent, and the furnace exceeding hot, the flame of the fire slew those men that took up Shadrach, Meshach, and Abed-nego. And these three men, Shadrach, Meshach, and Abed-nego, fell down bound into the midst of the burning fiery furnace."}], [{"ref": "Daniel 5:5", "text": "In the same hour came forth fingers of a man’s hand, and wrote over against the candlestick upon the plaister of the wall of the king’s palace: and the king saw the part of the hand that wrote."}], [{"ref": "Daniel 6:16", "text": "Then the king commanded, and they brought Daniel, and cast him into the den of lions. Now the king spake and said unto Daniel, Thy God whom thou servest continually, he will deliver thee."}]]'::jsonb, updated_at = now() where id = 'seq-daniel' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 16:13", "text": "Then Samuel took the horn of oil, and anointed him in the midst of his brethren: and the Spirit of the LORD came upon David from that day forward. So Samuel rose up, and went to Ramah."}], [{"ref": "1 Samuel 16:23", "text": "And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}, {"ref": "1 Samuel 17:48-50", "text": "And it came to pass, when the Philistine arose, and came and drew nigh to meet David, that David hasted, and ran toward the army to meet the Philistine. And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}], [{"ref": "1 Samuel 24:3-7", "text": "And he came to the sheepcotes by the way, where was a cave; and Saul went in to cover his feet: and David and his men remained in the sides of the cave. And the men of David said unto him, Behold the day of which the LORD said unto thee, Behold, I will deliver thine enemy into thine hand, that thou mayest do to him as it shall seem good unto thee. Then David arose, and cut off the skirt of Saul’s robe privily. And it came to pass afterward, that David’s heart smote him, because he had cut off Saul’s skirt. And he said unto his men, The LORD forbid that I should do this thing unto my master, the LORD’s anointed, to stretch forth mine hand against him, seeing he is the anointed of the LORD. So David stayed his servants with these words, and suffered them not to rise against Saul. But Saul rose up out of the cave, and went on his way."}], [{"ref": "2 Samuel 5:3", "text": "So all the elders of Israel came to the king to Hebron; and king David made a league with them in Hebron before the LORD: and they anointed David king over Israel."}]]'::jsonb, updated_at = now() where id = 'seq-david' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 11:2", "text": "And it came to pass in an eveningtide, that David arose from off his bed, and walked upon the roof of the king’s house: and from the roof he saw a woman washing herself; and the woman was very beautiful to look upon."}], [{"ref": "2 Samuel 11:14-15", "text": "And it came to pass in the morning, that David wrote a letter to Joab, and sent it by the hand of Uriah. And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die."}], [{"ref": "2 Samuel 12:7", "text": "And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;"}], [{"ref": "2 Samuel 12:13", "text": "And David said unto Nathan, I have sinned against the LORD. And Nathan said unto David, The LORD also hath put away thy sin; thou shalt not die."}], [{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}]]'::jsonb, updated_at = now() where id = 'seq-david_bathsheba' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Judges 4:4-5", "text": "And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time. And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment."}], [{"ref": "Judges 4:6", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun?"}], [{"ref": "Judges 4:14", "text": "And Deborah said unto Barak, Up; for this is the day in which the LORD hath delivered Sisera into thine hand: is not the LORD gone out before thee? So Barak went down from mount Tabor, and ten thousand men after him."}], [{"ref": "Judges 4:21", "text": "Then Jael Heber’s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died."}], [{"ref": "Judges 5:1-3", "text": "Then sang Deborah and Barak the son of Abinoam on that day, saying, Praise ye the LORD for the avenging of Israel, when the people willingly offered themselves. Hear, O ye kings; give ear, O ye princes; I, even I, will sing unto the LORD; I will sing praise to the LORD God of Israel."}]]'::jsonb, updated_at = now() where id = 'seq-deborah_barak' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Kings 17:1-6", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook."}], [{"ref": "1 Kings 17:9", "text": "Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee."}, {"ref": "1 Kings 17:15-16", "text": "And she went and did according to the saying of Elijah: and she, and he, and her house, did eat many days. And the barrel of meal wasted not, neither did the cruse of oil fail, according to the word of the LORD, which he spake by Elijah."}], [{"ref": "1 Kings 18:20", "text": "So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel."}, {"ref": "1 Kings 18:36-38", "text": "And it came to pass at the time of the offering of the evening sacrifice, that Elijah the prophet came near, and said, LORD God of Abraham, Isaac, and of Israel, let it be known this day that thou art God in Israel, and that I am thy servant, and that I have done all these things at thy word. Hear me, O LORD, hear me, that this people may know that thou art the LORD God, and that thou hast turned their heart back again. Then the fire of the LORD fell, and consumed the burnt sacrifice, and the wood, and the stones, and the dust, and licked up the water that was in the trench."}], [{"ref": "1 Kings 19:11-13", "text": "And he said, Go forth, and stand upon the mount before the LORD. And, behold, the LORD passed by, and a great and strong wind rent the mountains, and brake in pieces the rocks before the LORD; but the LORD was not in the wind: and after the wind an earthquake; but the LORD was not in the earthquake: And after the earthquake a fire; but the LORD was not in the fire: and after the fire a still small voice. And it was so, when Elijah heard it, that he wrapped his face in his mantle, and went out, and stood in the entering in of the cave. And, behold, there came a voice unto him, and said, What doest thou here, Elijah?"}], [{"ref": "2 Kings 2:11", "text": "And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven."}]]'::jsonb, updated_at = now() where id = 'seq-elijah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Kings 2:9", "text": "And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."}], [{"ref": "2 Kings 2:13-14", "text": "He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan; And he took the mantle of Elijah that fell from him, and smote the waters, and said, Where is the LORD God of Elijah? and when he also had smitten the waters, they parted hither and thither: and Elisha went over."}], [{"ref": "2 Kings 4:1-6", "text": "Now there cried a certain woman of the wives of the sons of the prophets unto Elisha, saying, Thy servant my husband is dead; and thou knowest that thy servant did fear the LORD: and the creditor is come to take unto him my two sons to be bondmen. And Elisha said unto her, What shall I do for thee? tell me, what hast thou in the house? And she said, Thine handmaid hath not any thing in the house, save a pot of oil. Then he said, Go, borrow thee vessels abroad of all thy neighbours, even empty vessels; borrow not a few. And when thou art come in, thou shalt shut the door upon thee and upon thy sons, and shalt pour out into all those vessels, and thou shalt set aside that which is full. So she went from him, and shut the door upon her and upon her sons, who brought the vessels to her; and she poured out. And it came to pass, when the vessels were full, that she said unto her son, Bring me yet a vessel. And he said unto her, There is not a vessel more. And the oil stayed."}], [{"ref": "2 Kings 4:35-36", "text": "Then he returned, and walked in the house to and fro; and went up, and stretched himself upon him: and the child sneezed seven times, and the child opened his eyes. And he called Gehazi, and said, Call this Shunammite. So he called her. And when she was come in unto him, he said, Take up thy son."}], [{"ref": "2 Kings 6:5-6", "text": "But as one was felling a beam, the axe head fell into the water: and he cried, and said, Alas, master! for it was borrowed. And the man of God said, Where fell it? And he shewed him the place. And he cut down a stick, and cast it in thither; and the iron did swim."}]]'::jsonb, updated_at = now() where id = 'seq-elisha_ministry' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}], [{"ref": "Esther 3:6", "text": "And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai."}], [{"ref": "Esther 5:1-2", "text": "Now it came to pass on the third day, that Esther put on her royal apparel, and stood in the inner court of the king’s house, over against the king’s house: and the king sat upon his royal throne in the royal house, over against the gate of the house. And it was so, when the king saw Esther the queen standing in the court, that she obtained favour in his sight: and the king held out to Esther the golden sceptre that was in his hand. So Esther drew near, and touched the top of the sceptre."}], [{"ref": "Esther 7:10", "text": "So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified."}]]'::jsonb, updated_at = now() where id = 'seq-esther' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 2:3", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."}], [{"ref": "Exodus 3:2-4", "text": "And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed. And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt. And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I."}], [{"ref": "Exodus 7:20", "text": "And Moses and Aaron did so, as the LORD commanded; and he lifted up the rod, and smote the waters that were in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that were in the river were turned to blood."}], [{"ref": "Exodus 12:21-23", "text": "Then Moses called for all the elders of Israel, and said unto them, Draw out and take you a lamb according to your families, and kill the passover. And ye shall take a bunch of hyssop, and dip it in the blood that is in the bason, and strike the lintel and the two side posts with the blood that is in the bason; and none of you shall go out at the door of his house until the morning. For the LORD will pass through to smite the Egyptians; and when he seeth the blood upon the lintel, and on the two side posts, the LORD will pass over the door, and will not suffer the destroyer to come in unto your houses to smite you."}, {"ref": "Exodus 12:28", "text": "And the children of Israel went away, and did as the LORD had commanded Moses and Aaron, so did they."}], [{"ref": "Exodus 14:22", "text": "And the children of Israel went into the midst of the sea upon the dry ground: and the waters were a wall unto them on their right hand, and on their left."}]]'::jsonb, updated_at = now() where id = 'seq-exodus' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Ezra 1:1-3", "text": "Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying, Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah. Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the LORD God of Israel, (he is the God,) which is in Jerusalem."}], [{"ref": "Ezra 3:10-11", "text": "And when the builders laid the foundation of the temple of the LORD, they set the priests in their apparel with trumpets, and the Levites the sons of Asaph with cymbals, to praise the LORD, after the ordinance of David king of Israel. And they sang together by course in praising and giving thanks unto the LORD; because he is good, for his mercy endureth for ever toward Israel. And all the people shouted with a great shout, when they praised the LORD, because the foundation of the house of the LORD was laid."}], [{"ref": "Ezra 4:4-5", "text": "Then the people of the land weakened the hands of the people of Judah, and troubled them in building, And hired counsellors against them, to frustrate their purpose, all the days of Cyrus king of Persia, even until the reign of Darius king of Persia."}], [{"ref": "Ezra 6:14-15", "text": "And the elders of the Jews builded, and they prospered through the prophesying of Haggai the prophet and Zechariah the son of Iddo. And they builded, and finished it, according to the commandment of the God of Israel, and according to the commandment of Cyrus, and Darius, and Artaxerxes king of Persia. And this house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king."}], [{"ref": "Ezra 7:6", "text": "This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}]]'::jsonb, updated_at = now() where id = 'seq-ezra_return' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "John 6:2", "text": "And a great multitude followed him, because they saw his miracles which he did on them that were diseased."}], [{"ref": "John 6:5", "text": "When Jesus then lifted up his eyes, and saw a great company come unto him, he saith unto Philip, Whence shall we buy bread, that these may eat?"}], [{"ref": "John 6:8-9", "text": "One of his disciples, Andrew, Simon Peter’s brother, saith unto him, There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"}], [{"ref": "John 6:10-11", "text": "And Jesus said, Make the men sit down. Now there was much grass in the place. So the men sat down, in number about five thousand. And Jesus took the loaves; and when he had given thanks, he distributed to the disciples, and the disciples to them that were set down; and likewise of the fishes as much as they would."}], [{"ref": "John 6:12-13", "text": "When they were filled, he said unto his disciples, Gather up the fragments that remain, that nothing be lost. Therefore they gathered them together, and filled twelve baskets with the fragments of the five barley loaves, which remained over and above unto them that had eaten."}]]'::jsonb, updated_at = now() where id = 'seq-feeding' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Daniel 3:1", "text": "Nebuchadnezzar the king made an image of gold, whose height was threescore cubits, and the breadth thereof six cubits: he set it up in the plain of Dura, in the province of Babylon."}], [{"ref": "Daniel 3:12", "text": "There are certain Jews whom thou hast set over the affairs of the province of Babylon, Shadrach, Meshach, and Abed-nego; these men, O king, have not regarded thee: they serve not thy gods, nor worship the golden image which thou hast set up."}, {"ref": "Daniel 3:16-18", "text": "Shadrach, Meshach, and Abed-nego, answered and said to the king, O Nebuchadnezzar, we are not careful to answer thee in this matter. If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king. But if not, be it known unto thee, O king, that we will not serve thy gods, nor worship the golden image which thou hast set up."}], [{"ref": "Daniel 3:19", "text": "Then was Nebuchadnezzar full of fury, and the form of his visage was changed against Shadrach, Meshach, and Abed-nego: therefore he spake, and commanded that they should heat the furnace one seven times more than it was wont to be heated."}], [{"ref": "Daniel 3:24-25", "text": "Then Nebuchadnezzar the king was astonied, and rose up in haste, and spake, and said unto his counsellors, Did not we cast three men bound into the midst of the fire? They answered and said unto the king, True, O king. He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God."}], [{"ref": "Daniel 3:26-27", "text": "Then Nebuchadnezzar came near to the mouth of the burning fiery furnace, and spake, and said, Shadrach, Meshach, and Abed-nego, ye servants of the most high God, come forth, and come hither. Then Shadrach, Meshach, and Abed-nego, came forth of the midst of the fire. And the princes, governors, and captains, and the king’s counsellors, being gathered together, saw these men, upon whose bodies the fire had no power, nor was an hair of their head singed, neither were their coats changed, nor the smell of fire had passed on them."}]]'::jsonb, updated_at = now() where id = 'seq-fiery_furnace' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Judges 6:11-12", "text": "And there came an angel of the LORD, and sat under an oak which was in Ophrah, that pertained unto Joash the Abi-ezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites. And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour."}], [{"ref": "Judges 6:36-40", "text": "And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said, Behold, I will put a fleece of wool in the floor; and if the dew be on the fleece only, and it be dry upon all the earth beside, then shall I know that thou wilt save Israel by mine hand, as thou hast said. And it was so: for he rose up early on the morrow, and thrust the fleece together, and wringed the dew out of the fleece, a bowl full of water. And Gideon said unto God, Let not thine anger be hot against me, and I will speak but this once: let me prove, I pray thee, but this once with the fleece; let it now be dry only upon the fleece, and upon all the ground let there be dew. And God did so that night: for it was dry upon the fleece only, and there was dew on all the ground."}], [{"ref": "Judges 7:4-7", "text": "And the LORD said unto Gideon, The people are yet too many; bring them down unto the water, and I will try them for thee there: and it shall be, that of whom I say unto thee, This shall go with thee, the same shall go with thee; and of whomsoever I say unto thee, This shall not go with thee, the same shall not go. So he brought down the people unto the water: and the LORD said unto Gideon, Every one that lappeth of the water with his tongue, as a dog lappeth, him shalt thou set by himself; likewise every one that boweth down upon his knees to drink. And the number of them that lapped, putting their hand to their mouth, were three hundred men: but all the rest of the people bowed down upon their knees to drink water. And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place."}], [{"ref": "Judges 7:20", "text": "And the three companies blew the trumpets, and brake the pitchers, and held the lamps in their left hands, and the trumpets in their right hands to blow withal: and they cried, The sword of the LORD, and of Gideon."}]]'::jsonb, updated_at = now() where id = 'seq-gideon' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9-10", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore."}], [{"ref": "1 Samuel 1:13", "text": "Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken."}], [{"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}], [{"ref": "1 Samuel 1:26-28", "text": "And she said, Oh my lord, as thy soul liveth, my lord, I am the woman that stood by thee here, praying unto the LORD. For this child I prayed; and the LORD hath given me my petition which I asked of him: Therefore also I have lent him to the LORD; as long as he liveth he shall be lent to the LORD. And he worshipped the LORD there."}], [{"ref": "1 Samuel 2:1", "text": "And Hannah prayed, and said, My heart rejoiceth in the LORD, mine horn is exalted in the LORD: my mouth is enlarged over mine enemies; because I rejoice in thy salvation."}]]'::jsonb, updated_at = now() where id = 'seq-hannah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Kings 18:1-4", "text": "Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign. Twenty and five years old was he when he began to reign; and he reigned twenty and nine years in Jerusalem. His mother’s name also was Abi, the daughter of Zachariah. And he did that which was right in the sight of the LORD, according to all that David his father did. He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan."}], [{"ref": "2 Kings 18:13", "text": "Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fenced cities of Judah, and took them."}], [{"ref": "2 Kings 19:14", "text": "And Hezekiah received the letter of the hand of the messengers, and read it: and Hezekiah went up into the house of the LORD, and spread it before the LORD."}], [{"ref": "2 Kings 19:35", "text": "And it came to pass that night, that the angel of the LORD went out, and smote in the camp of the Assyrians an hundred fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses."}], [{"ref": "2 Kings 19:36-37", "text": "So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh. And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword: and they escaped into the land of Armenia. And Esar-haddon his son reigned in his stead."}]]'::jsonb, updated_at = now() where id = 'seq-hezekiah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 24:2-4", "text": "And Abraham said unto his eldest servant of his house, that ruled over all that he had, Put, I pray thee, thy hand under my thigh: And I will make thee swear by the LORD, the God of heaven, and the God of the earth, that thou shalt not take a wife unto my son of the daughters of the Canaanites, among whom I dwell: But thou shalt go unto my country, and to my kindred, and take a wife unto my son Isaac."}], [{"ref": "Genesis 24:15-19", "text": "And it came to pass, before he had done speaking, that, behold, Rebekah came out, who was born to Bethuel, son of Milcah, the wife of Nahor, Abraham’s brother, with her pitcher upon her shoulder. And the damsel was very fair to look upon, a virgin, neither had any man known her: and she went down to the well, and filled her pitcher, and came up. And the servant ran to meet her, and said, Let me, I pray thee, drink a little water of thy pitcher. And she said, Drink, my lord: and she hasted, and let down her pitcher upon her hand, and gave him drink. And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking."}], [{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 24:58", "text": "And they called Rebekah, and said unto her, Wilt thou go with this man? And she said, I will go."}], [{"ref": "Genesis 24:67", "text": "And Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother’s death."}]]'::jsonb, updated_at = now() where id = 'seq-isaac_rebekah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 22:1-2", "text": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}], [{"ref": "Genesis 22:3", "text": "And Abraham rose up early in the morning, and saddled his ass, and took two of his young men with him, and Isaac his son, and clave the wood for the burnt offering, and rose up, and went unto the place of which God had told him."}], [{"ref": "Genesis 22:7", "text": "And Isaac spake unto Abraham his father, and said, My father: and he said, Here am I, my son. And he said, Behold the fire and the wood: but where is the lamb for a burnt offering?"}], [{"ref": "Genesis 22:10-11", "text": "And Abraham stretched forth his hand, and took the knife to slay his son. And the angel of the LORD called unto him out of heaven, and said, Abraham, Abraham: and he said, Here am I."}], [{"ref": "Genesis 22:13", "text": "And Abraham lifted up his eyes, and looked, and behold behind him a ram caught in a thicket by his horns: and Abraham went and took the ram, and offered him up for a burnt offering in the stead of his son."}]]'::jsonb, updated_at = now() where id = 'seq-isaac_sacrifice' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 25:26", "text": "And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 28:10-12", "text": "And Jacob went out from Beer-sheba, and went toward Haran. And he lighted upon a certain place, and tarried there all night, because the sun was set; and he took of the stones of that place, and put them for his pillows, and lay down in that place to sleep. And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it."}], [{"ref": "Genesis 32:24-28", "text": "And Jacob was left alone; and there wrestled a man with him until the breaking of the day. And when he saw that he prevailed not against him, he touched the hollow of his thigh; and the hollow of Jacob’s thigh was out of joint, as he wrestled with him. And he said, Let me go, for the day breaketh. And he said, I will not let thee go, except thou bless me. And he said unto him, What is thy name? And he said, Jacob. And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed."}]]'::jsonb, updated_at = now() where id = 'seq-jacob' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 29:9-10", "text": "And while he yet spake with them, Rachel came with her father’s sheep: for she kept them. And it came to pass, when Jacob saw Rachel the daughter of Laban his mother’s brother, and the sheep of Laban his mother’s brother, that Jacob went near, and rolled the stone from the well’s mouth, and watered the flock of Laban his mother’s brother."}], [{"ref": "Genesis 29:20", "text": "And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her."}], [{"ref": "Genesis 29:25", "text": "And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me?"}], [{"ref": "Genesis 29:30", "text": "And he went in also unto Rachel, and he loved also Rachel more than Leah, and served with him yet seven other years."}]]'::jsonb, updated_at = now() where id = 'seq-jacob_rachel' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Mark 5:22-23", "text": "And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet, And besought him greatly, saying, My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live."}], [{"ref": "Mark 5:25-28", "text": "And a certain woman, which had an issue of blood twelve years, And had suffered many things of many physicians, and had spent all that she had, and was nothing bettered, but rather grew worse, When she had heard of Jesus, came in the press behind, and touched his garment. For she said, If I may touch but his clothes, I shall be whole."}], [{"ref": "Mark 5:30", "text": "And Jesus, immediately knowing in himself that virtue had gone out of him, turned him about in the press, and said, Who touched my clothes?"}], [{"ref": "Mark 5:35", "text": "While he yet spake, there came from the ruler of the synagogue’s house certain which said, Thy daughter is dead: why troublest thou the Master any further?"}], [{"ref": "Mark 5:41-42", "text": "And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise. And straightway the damsel arose, and walked; for she was of the age of twelve years. And they were astonished with a great astonishment."}]]'::jsonb, updated_at = now() where id = 'seq-jairus_daughter' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Joshua 2:1", "text": "And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there."}, {"ref": "Joshua 2:4-6", "text": "And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were: And it came to pass about the time of shutting of the gate, when it was dark, that the men went out: whither the men went I wot not: pursue after them quickly; for ye shall overtake them. But she had brought them up to the roof of the house, and hid them with the stalks of flax, which she had laid in order upon the roof."}], [{"ref": "Joshua 3:17", "text": "And the priests that bare the ark of the covenant of the LORD stood firm on dry ground in the midst of Jordan, and all the Israelites passed over on dry ground, until all the people were passed clean over Jordan."}], [{"ref": "Joshua 6:11-14", "text": "So the ark of the LORD compassed the city, going about it once: and they came into the camp, and lodged in the camp. And Joshua rose early in the morning, and the priests took up the ark of the LORD. And seven priests bearing seven trumpets of rams’ horns before the ark of the LORD went on continually, and blew with the trumpets: and the armed men went before them; but the rereward came after the ark of the LORD, the priests going on, and blowing with the trumpets. And the second day they compassed the city once, and returned into the camp: so they did six days."}], [{"ref": "Joshua 6:15", "text": "And it came to pass on the seventh day, that they rose early about the dawning of the day, and compassed the city after the same manner seven times: only on that day they compassed the city seven times."}], [{"ref": "Joshua 6:20", "text": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}]]'::jsonb, updated_at = now() where id = 'seq-jericho' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Jonah 1:1-2", "text": "Now the word of the LORD came unto Jonah the son of Amittai, saying, Arise, go to Nineveh, that great city, and cry against it; for their wickedness is come up before me."}], [{"ref": "Jonah 1:3", "text": "But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD."}], [{"ref": "Jonah 1:17", "text": "Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights."}], [{"ref": "Jonah 3:4", "text": "And Jonah began to enter into the city a day’s journey, and he cried, and said, Yet forty days, and Nineveh shall be overthrown."}], [{"ref": "Jonah 4:6", "text": "And the LORD God prepared a gourd, and made it to come up over Jonah, that it might be a shadow over his head, to deliver him from his grief. So Jonah was exceeding glad of the gourd."}]]'::jsonb, updated_at = now() where id = 'seq-jonah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 37:3", "text": "Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."}], [{"ref": "Genesis 37:26-28", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content. Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt."}], [{"ref": "Genesis 39:1-4", "text": "And Joseph was brought down to Egypt; and Potiphar, an officer of Pharaoh, captain of the guard, an Egyptian, bought him of the hands of the Ishmeelites, which had brought him down thither. And the LORD was with Joseph, and he was a prosperous man; and he was in the house of his master the Egyptian. And his master saw that the LORD was with him, and that the LORD made all that he did to prosper in his hand. And Joseph found grace in his sight, and he served him: and he made him overseer over his house, and all that he had he put into his hand."}], [{"ref": "Genesis 41:25-30", "text": "And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do. The seven good kine are seven years; and the seven good ears are seven years: the dream is one. And the seven thin and ill favoured kine that came up after them are seven years; and the seven empty ears blasted with the east wind shall be seven years of famine. This is the thing which I have spoken unto Pharaoh: What God is about to do he sheweth unto Pharaoh. Behold, there come seven years of great plenty throughout all the land of Egypt: And there shall arise after them seven years of famine; and all the plenty shall be forgotten in the land of Egypt; and the famine shall consume the land;"}], [{"ref": "Genesis 45:4", "text": "And Joseph said unto his brethren, Come near to me, I pray you. And they came near. And he said, I am Joseph your brother, whom ye sold into Egypt."}]]'::jsonb, updated_at = now() where id = 'seq-joseph' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 42:3", "text": "And Joseph’s ten brethren went down to buy corn in Egypt."}], [{"ref": "Genesis 42:24", "text": "And he turned himself about from them, and wept; and returned to them again, and communed with them, and took from them Simeon, and bound him before their eyes."}], [{"ref": "Genesis 43:15", "text": "And the men took that present, and they took double money in their hand, and Benjamin; and rose up, and went down to Egypt, and stood before Joseph."}], [{"ref": "Genesis 44:12", "text": "And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin’s sack."}], [{"ref": "Genesis 45:1-3", "text": "Then Joseph could not refrain himself before all them that stood by him; and he cried, Cause every man to go out from me. And there stood no man with him, while Joseph made himself known unto his brethren. And he wept aloud: and the Egyptians and the house of Pharaoh heard. And Joseph said unto his brethren, I am Joseph; doth my father yet live? And his brethren could not answer him; for they were troubled at his presence."}]]'::jsonb, updated_at = now() where id = 'seq-joseph_brothers' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Joshua 2:1-4", "text": "And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there. And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country. And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country. And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were:"}], [{"ref": "Joshua 3:17", "text": "And the priests that bare the ark of the covenant of the LORD stood firm on dry ground in the midst of Jordan, and all the Israelites passed over on dry ground, until all the people were passed clean over Jordan."}], [{"ref": "Joshua 6:1-2", "text": "Now Jericho was straitly shut up because of the children of Israel: none went out, and none came in. And the LORD said unto Joshua, See, I have given into thine hand Jericho, and the king thereof, and the mighty men of valour."}, {"ref": "Joshua 6:20", "text": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}], [{"ref": "Joshua 10:12-13", "text": "Then spake Joshua to the LORD in the day when the LORD delivered up the Amorites before the children of Israel, and he said in the sight of Israel, Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon. And the sun stood still, and the moon stayed, until the people had avenged themselves upon their enemies. Is not this written in the book of Jasher? So the sun stood still in the midst of heaven, and hasted not to go down about a whole day."}]]'::jsonb, updated_at = now() where id = 'seq-joshua' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Kings 22:1", "text": "Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath."}], [{"ref": "2 Kings 22:8", "text": "And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it."}], [{"ref": "2 Kings 22:10-11", "text": "And Shaphan the scribe shewed the king, saying, Hilkiah the priest hath delivered me a book. And Shaphan read it before the king. And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes."}], [{"ref": "2 Kings 23:3", "text": "And the king stood by a pillar, and made a covenant before the LORD, to walk after the LORD, and to keep his commandments and his testimonies and his statutes with all their heart and all their soul, to perform the words of this covenant that were written in this book. And all the people stood to the covenant."}], [{"ref": "2 Kings 23:21", "text": "And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant."}]]'::jsonb, updated_at = now() where id = 'seq-josiah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "John 11:1-3", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.) Therefore his sisters sent unto him, saying, Lord, behold, he whom thou lovest is sick."}], [{"ref": "John 11:14-17", "text": "Then said Jesus unto them plainly, Lazarus is dead. And I am glad for your sakes that I was not there, to the intent ye may believe; nevertheless let us go unto him. Then said Thomas, which is called Didymus, unto his fellowdisciples, Let us also go, that we may die with him. Then when Jesus came, he found that he had lain in the grave four days already."}], [{"ref": "John 11:25", "text": "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"}], [{"ref": "John 11:35", "text": "Jesus wept."}], [{"ref": "John 11:43-44", "text": "And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go."}]]'::jsonb, updated_at = now() where id = 'seq-lazarus' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 13:11", "text": "Then Lot chose him all the plain of Jordan; and Lot journeyed east: and they separated themselves the one from the other."}], [{"ref": "Genesis 14:12-14", "text": "And they took Lot, Abram’s brother’s son, who dwelt in Sodom, and his goods, and departed. And there came one that had escaped, and told Abram the Hebrew; for he dwelt in the plain of Mamre the Amorite, brother of Eshcol, and brother of Aner: and these were confederate with Abram. And when Abram heard that his brother was taken captive, he armed his trained servants, born in his own house, three hundred and eighteen, and pursued them unto Dan."}], [{"ref": "Genesis 19:1", "text": "And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground;"}], [{"ref": "Genesis 19:23-26", "text": "The sun was risen upon the earth when Lot entered into Zoar. Then the LORD rained upon Sodom and upon Gomorrah brimstone and fire from the LORD out of heaven; And he overthrew those cities, and all the plain, and all the inhabitants of the cities, and that which grew upon the ground. But his wife looked back from behind him, and she became a pillar of salt."}]]'::jsonb, updated_at = now() where id = 'seq-lot_sodom' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Matthew 3:16", "text": "And Jesus, when he was baptized, went up straightway out of the water: and, lo, the heavens were opened unto him, and he saw the Spirit of God descending like a dove, and lighting upon him:"}], [{"ref": "Matthew 4:1", "text": "Then was Jesus led up of the Spirit into the wilderness to be tempted of the devil."}], [{"ref": "Matthew 4:18-20", "text": "And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers. And he saith unto them, Follow me, and I will make you fishers of men. And they straightway left their nets, and followed him."}], [{"ref": "Matthew 5:1-2", "text": "And seeing the multitudes, he went up into a mountain: and when he was set, his disciples came unto him: And he opened his mouth, and taught them, saying,"}]]'::jsonb, updated_at = now() where id = 'seq-ministry' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 1:22", "text": "And Pharaoh charged all his people, saying, Every son that is born ye shall cast into the river, and every daughter ye shall save alive."}], [{"ref": "Exodus 2:2-3", "text": "And the woman conceived, and bare a son: and when she saw him that he was a goodly child, she hid him three months. And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."}], [{"ref": "Exodus 2:5-6", "text": "And the daughter of Pharaoh came down to wash herself at the river; and her maidens walked along by the river’s side; and when she saw the ark among the flags, she sent her maid to fetch it. And when she had opened it, she saw the child: and, behold, the babe wept. And she had compassion on him, and said, This is one of the Hebrews’ children."}], [{"ref": "Exodus 2:15", "text": "Now when Pharaoh heard this thing, he sought to slay Moses. But Moses fled from the face of Pharaoh, and dwelt in the land of Midian: and he sat down by a well."}], [{"ref": "Exodus 3:2-4", "text": "And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed. And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt. And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I."}]]'::jsonb, updated_at = now() where id = 'seq-moses_early' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "2 Kings 5:2-3", "text": "And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naaman’s wife. And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy."}], [{"ref": "2 Kings 5:7", "text": "And it came to pass, when the king of Israel had read the letter, that he rent his clothes, and said, Am I God, to kill and to make alive, that this man doth send unto me to recover a man of his leprosy? wherefore consider, I pray you, and see how he seeketh a quarrel against me."}], [{"ref": "2 Kings 5:10", "text": "And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean."}], [{"ref": "2 Kings 5:11-12", "text": "But Naaman was wroth, and went away, and said, Behold, I thought, He will surely come out to me, and stand, and call on the name of the LORD his God, and strike his hand over the place, and recover the leper. Are not Abana and Pharpar, rivers of Damascus, better than all the waters of Israel? may I not wash in them, and be clean? So he turned and went away in a rage."}], [{"ref": "2 Kings 5:14", "text": "Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."}]]'::jsonb, updated_at = now() where id = 'seq-naaman' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 1:26-31", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary. And the angel came in unto her, and said, Hail, thou that art highly favoured, the Lord is with thee: blessed art thou among women. And when she saw him, she was troubled at his saying, and cast in her mind what manner of salutation this should be. And the angel said unto her, Fear not, Mary: for thou hast found favour with God. And, behold, thou shalt conceive in thy womb, and bring forth a son, and shalt call his name JESUS."}], [{"ref": "Luke 2:4-5", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:) To be taxed with Mary his espoused wife, being great with child."}], [{"ref": "Luke 2:8-14", "text": "And there were in the same country shepherds abiding in the field, keeping watch over their flock by night. And, lo, the angel of the Lord came upon them, and the glory of the Lord shone round about them: and they were sore afraid. And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord. And this shall be a sign unto you; Ye shall find the babe wrapped in swaddling clothes, lying in a manger. And suddenly there was with the angel a multitude of the heavenly host praising God, and saying, Glory to God in the highest, and on earth peace, good will toward men."}], [{"ref": "Luke 2:25-28", "text": "And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him. And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord’s Christ. And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law, Then took he him up in his arms, and blessed God, and said,"}], [{"ref": "Luke 2:42-46", "text": "And when he was twelve years old, they went up to Jerusalem after the custom of the feast. And when they had fulfilled the days, as they returned, the child Jesus tarried behind in Jerusalem; and Joseph and his mother knew not of it. But they, supposing him to have been in the company, went a day’s journey; and they sought him among their kinsfolk and acquaintance. And when they found him not, they turned back again to Jerusalem, seeking him. And it came to pass, that after three days they found him in the temple, sitting in the midst of the doctors, both hearing them, and asking them questions."}]]'::jsonb, updated_at = now() where id = 'seq-nativity' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Nehemiah 1:3-4", "text": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire. And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}], [{"ref": "Nehemiah 2:1-2", "text": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence. Wherefore the king said unto me, Why is thy countenance sad, seeing thou art not sick? this is nothing else but sorrow of heart. Then I was very sore afraid,"}], [{"ref": "Nehemiah 2:13", "text": "And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire."}], [{"ref": "Nehemiah 4:1-3", "text": "But it came to pass, that when Sanballat heard that we builded the wall, he was wroth, and took great indignation, and mocked the Jews. And he spake before his brethren and the army of Samaria, and said, What do these feeble Jews? will they fortify themselves? will they sacrifice? will they make an end in a day? will they revive the stones out of the heaps of the rubbish which are burned? Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall."}], [{"ref": "Nehemiah 6:15", "text": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}]]'::jsonb, updated_at = now() where id = 'seq-nehemiah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Genesis 6:13-14", "text": "And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth. Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."}], [{"ref": "Genesis 7:7-9", "text": "And Noah went in, and his sons, and his wife, and his sons’ wives with him, into the ark, because of the waters of the flood. Of clean beasts, and of beasts that are not clean, and of fowls, and of every thing that creepeth upon the earth, There went in two and two unto Noah into the ark, the male and the female, as God had commanded Noah."}], [{"ref": "Genesis 7:12", "text": "And the rain was upon the earth forty days and forty nights."}], [{"ref": "Genesis 8:10-11", "text": "And he stayed yet other seven days; and again he sent forth the dove out of the ark; And the dove came in to him in the evening; and, lo, in her mouth was an olive leaf pluckt off: so Noah knew that the waters were abated from off the earth."}], [{"ref": "Genesis 9:12-13", "text": "And God said, This is the token of the covenant which I make between me and you and every living creature that is with you, for perpetual generations: I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth."}]]'::jsonb, updated_at = now() where id = 'seq-noah' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Matthew 21:8-10", "text": "And a very great multitude spread their garments in the way; others cut down branches from the trees, and strawed them in the way. And the multitudes that went before, and that followed, cried, saying, Hosanna to the Son of David: Blessed is he that cometh in the name of the Lord; Hosanna in the highest. And when he was come into Jerusalem, all the city was moved, saying, Who is this?"}], [{"ref": "Matthew 26:26", "text": "And as they were eating, Jesus took bread, and blessed it, and brake it, and gave it to the disciples, and said, Take, eat; this is my body."}], [{"ref": "Matthew 26:36-39", "text": "Then cometh Jesus with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder. And he took with him Peter and the two sons of Zebedee, and began to be sorrowful and very heavy. Then saith he unto them, My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me. And he went a little further, and fell on his face, and prayed, saying, O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt."}], [{"ref": "Matthew 27:35", "text": "And they crucified him, and parted his garments, casting lots: that it might be fulfilled which was spoken by the prophet, They parted my garments among them, and upon my vesture did they cast lots."}], [{"ref": "Matthew 28:5-6", "text": "And the angel answered and said unto the women, Fear not ye: for I know that ye seek Jesus, which was crucified. He is not here: for he is risen, as he said. Come, see the place where the Lord lay."}]]'::jsonb, updated_at = now() where id = 'seq-passion' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 9:3-6", "text": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks. And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do."}], [{"ref": "Acts 13:2", "text": "As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them."}], [{"ref": "Acts 16:9", "text": "And a vision appeared to Paul in the night; There stood a man of Macedonia, and prayed him, saying, Come over into Macedonia, and help us."}], [{"ref": "Acts 17:22", "text": "Then Paul stood in the midst of Mars’ hill, and said, Ye men of Athens, I perceive that in all things ye are too superstitious."}], [{"ref": "Acts 27:41-44", "text": "And falling into a place where two seas met, they ran the ship aground; and the forepart stuck fast, and remained unmoveable, but the hinder part was broken with the violence of the waves. And the soldiers’ counsel was to kill the prisoners, lest any of them should swim out, and escape. But the centurion, willing to save Paul, kept them from their purpose; and commanded that they which could swim should cast themselves first into the sea, and get to land: And the rest, some on boards, and some on broken pieces of the ship. And so it came to pass, that they escaped all safe to land."}, {"ref": "Acts 28:1", "text": "And when they were escaped, then they knew that the island was called Melita."}]]'::jsonb, updated_at = now() where id = 'seq-paul' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:16-18", "text": "And it came to pass, as we went to prayer, a certain damsel possessed with a spirit of divination met us, which brought her masters much gain by soothsaying: The same followed Paul and us, and cried, saying, These men are the servants of the most high God, which shew unto us the way of salvation. And this did she many days. But Paul, being grieved, turned and said to the spirit, I command thee in the name of Jesus Christ to come out of her. And he came out the same hour."}], [{"ref": "Acts 16:19-24", "text": "And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers, And brought them to the magistrates, saying, These men, being Jews, do exceedingly trouble our city, And teach customs, which are not lawful for us to receive, neither to observe, being Romans. And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them. And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely: Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks."}], [{"ref": "Acts 16:25", "text": "And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}], [{"ref": "Acts 16:27-33", "text": "And the keeper of the prison awaking out of his sleep, and seeing the prison doors open, he drew out his sword, and would have killed himself, supposing that the prisoners had been fled. But Paul cried with a loud voice, saying, Do thyself no harm: for we are all here. Then he called for a light, and sprang in, and came trembling, and fell down before Paul and Silas, And brought them out, and said, Sirs, what must I do to be saved? And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house. And they spake unto him the word of the Lord, and to all that were in his house. And he took them the same hour of the night, and washed their stripes; and was baptized, he and all his, straightway."}]]'::jsonb, updated_at = now() where id = 'seq-paul_philippi' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 10:3", "text": "He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius."}], [{"ref": "Acts 10:9-11", "text": "On the morrow, as they went on their journey, and drew nigh unto the city, Peter went up upon the housetop to pray about the sixth hour: And he became very hungry, and would have eaten: but while they made ready, he fell into a trance, And saw heaven opened, and a certain vessel descending unto him, as it had been a great sheet knit at the four corners, and let down to the earth:"}], [{"ref": "Acts 10:24", "text": "And the morrow after they entered into Cæsarea. And Cornelius waited for them, and had called together his kinsmen and near friends."}], [{"ref": "Acts 10:44", "text": "While Peter yet spake these words, the Holy Ghost fell on all them which heard the word."}], [{"ref": "Acts 10:46-48", "text": "For they heard them speak with tongues, and magnify God. Then answered Peter, Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we? And he commanded them to be baptized in the name of the Lord. Then prayed they him to tarry certain days."}]]'::jsonb, updated_at = now() where id = 'seq-peter_cornelius' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 22:33-34", "text": "And he said unto him, Lord, I am ready to go with thee, both into prison, and to death. And he said, I tell thee, Peter, the cock shall not crow this day, before that thou shalt thrice deny that thou knowest me."}], [{"ref": "Luke 22:54", "text": "Then took they him, and led him, and brought him into the high priest’s house. And Peter followed afar off."}], [{"ref": "Luke 22:55-57", "text": "And when they had kindled a fire in the midst of the hall, and were set down together, Peter sat down among them. But a certain maid beheld him as he sat by the fire, and earnestly looked upon him, and said, This man was also with him. And he denied him, saying, Woman, I know him not."}], [{"ref": "Luke 22:61", "text": "And the Lord turned, and looked upon Peter. And Peter remembered the word of the Lord, how he had said unto him, Before the cock crow, thou shalt deny me thrice."}], [{"ref": "Luke 22:62", "text": "And Peter went out, and wept bitterly."}]]'::jsonb, updated_at = now() where id = 'seq-peter_denial' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 12:1-2", "text": "Now about that time Herod the king stretched forth his hands to vex certain of the church. And he killed James the brother of John with the sword."}], [{"ref": "Acts 12:6", "text": "And when Herod would have brought him forth, the same night Peter was sleeping between two soldiers, bound with two chains: and the keepers before the door kept the prison."}], [{"ref": "Acts 12:7", "text": "And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands."}], [{"ref": "Acts 12:10", "text": "When they were past the first and the second ward, they came unto the iron gate that leadeth unto the city; which opened to them of his own accord: and they went out, and passed on through one street; and forthwith the angel departed from him."}], [{"ref": "Acts 12:13-14", "text": "And as Peter knocked at the door of the gate, a damsel came to hearken, named Rhoda. And when she knew Peter’s voice, she opened not the gate for gladness, but ran in, and told how Peter stood before the gate."}]]'::jsonb, updated_at = now() where id = 'seq-peter_prison' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 8:26", "text": "And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert."}], [{"ref": "Acts 8:27-28", "text": "And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship, Was returning, and sitting in his chariot read Esaias the prophet."}], [{"ref": "Acts 8:29-30", "text": "Then the Spirit said unto Philip, Go near, and join thyself to this chariot. And Philip ran thither to him, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?"}], [{"ref": "Acts 8:38", "text": "And he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him."}], [{"ref": "Acts 8:39", "text": "And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing."}]]'::jsonb, updated_at = now() where id = 'seq-philip_ethiopian' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 7:20", "text": "And Moses and Aaron did so, as the LORD commanded; and he lifted up the rod, and smote the waters that were in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that were in the river were turned to blood."}], [{"ref": "Exodus 8:6", "text": "And Aaron stretched out his hand over the waters of Egypt; and the frogs came up, and covered the land of Egypt."}], [{"ref": "Exodus 8:17", "text": "And they did so; for Aaron stretched out his hand with his rod, and smote the dust of the earth, and it became lice in man, and in beast; all the dust of the land became lice throughout all the land of Egypt."}], [{"ref": "Exodus 10:22", "text": "And Moses stretched forth his hand toward heaven; and there was a thick darkness in all the land of Egypt three days:"}], [{"ref": "Exodus 12:29", "text": "And it came to pass, that at midnight the LORD smote all the firstborn in the land of Egypt, from the firstborn of Pharaoh that sat on his throne unto the firstborn of the captive that was in the dungeon; and all the firstborn of cattle."}]]'::jsonb, updated_at = now() where id = 'seq-plagues' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 15:11-12", "text": "And he said, A certain man had two sons: And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living."}], [{"ref": "Luke 15:13", "text": "And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living."}], [{"ref": "Luke 15:13-15", "text": "And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living. And when he had spent all, there arose a mighty famine in that land; and he began to be in want. And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine."}], [{"ref": "Luke 15:20", "text": "And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him."}], [{"ref": "Luke 15:25-28", "text": "Now his elder son was in the field: and as he came and drew nigh to the house, he heard musick and dancing. And he called one of the servants, and asked what these things meant. And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound. And he was angry, and would not go in: therefore came his father out, and intreated him."}]]'::jsonb, updated_at = now() where id = 'seq-prodigal' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 24:1-3", "text": "Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them. And they found the stone rolled away from the sepulchre. And they entered in, and found not the body of the Lord Jesus."}, {"ref": "Luke 24:10", "text": "It was Mary Magdalene, and Joanna, and Mary the mother of James, and other women that were with them, which told these things unto the apostles."}], [{"ref": "Luke 24:13", "text": "And, behold, two of them went that same day to a village called Emmaus, which was from Jerusalem about threescore furlongs."}], [{"ref": "Luke 24:36", "text": "And as they thus spake, Jesus himself stood in the midst of them, and saith unto them, Peace be unto you."}], [{"ref": "Luke 24:51", "text": "And it came to pass, while he blessed them, he was parted from them, and carried up into heaven."}]]'::jsonb, updated_at = now() where id = 'seq-resurrection' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Ruth 1:14-18", "text": "And they lifted up their voice, and wept again: and Orpah kissed her mother in law; but Ruth clave unto her. And she said, Behold, thy sister in law is gone back unto her people, and unto her gods: return thou after thy sister in law. And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God: Where thou diest, will I die, and there will I be buried: the LORD do so to me, and more also, if ought but death part thee and me. When she saw that she was stedfastly minded to go with her, then she left speaking unto her."}], [{"ref": "Ruth 2:2-3", "text": "And Ruth the Moabitess said unto Naomi, Let me now go to the field, and glean ears of corn after him in whose sight I shall find grace. And she said unto her, Go, my daughter. And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech."}], [{"ref": "Ruth 3:9", "text": "And he said, Who art thou? And she answered, I am Ruth thine handmaid: spread therefore thy skirt over thine handmaid; for thou art a near kinsman."}], [{"ref": "Ruth 4:13", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son."}], [{"ref": "Ruth 4:17", "text": "And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."}]]'::jsonb, updated_at = now() where id = 'seq-ruth' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 10:30", "text": "And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead."}], [{"ref": "Luke 10:31", "text": "And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side."}], [{"ref": "Luke 10:32", "text": "And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side."}], [{"ref": "Luke 10:33-34", "text": "But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him, And went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him."}], [{"ref": "Luke 10:35", "text": "And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee."}]]'::jsonb, updated_at = now() where id = 'seq-samaritan' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Judges 13:3-5", "text": "And the angel of the LORD appeared unto the woman, and said unto her, Behold now, thou art barren, and bearest not: but thou shalt conceive, and bear a son. Now therefore beware, I pray thee, and drink not wine nor strong drink, and eat not any unclean thing: For, lo, thou shalt conceive, and bear a son; and no razor shall come on his head: for the child shall be a Nazarite unto God from the womb: and he shall begin to deliver Israel out of the hand of the Philistines."}], [{"ref": "Judges 14:5-6", "text": "Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him. And the Spirit of the LORD came mightily upon him, and he rent him as he would have rent a kid, and he had nothing in his hand: but he told not his father or his mother what he had done."}], [{"ref": "Judges 16:4", "text": "And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."}], [{"ref": "Judges 16:30", "text": "And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life."}]]'::jsonb, updated_at = now() where id = 'seq-samson' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9-11", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}], [{"ref": "1 Samuel 3:8-10", "text": "And the LORD called Samuel again the third time. And he arose and went to Eli, and said, Here am I; for thou didst call me. And Eli perceived that the LORD had called the child. Therefore Eli said unto Samuel, Go, lie down: and it shall be, if he call thee, that thou shalt say, Speak, LORD; for thy servant heareth. So Samuel went and lay down in his place. And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth."}], [{"ref": "1 Samuel 9:27", "text": "And as they were going down to the end of the city, Samuel said to Saul, Bid the servant pass on before us, (and he passed on,) but stand thou still a while, that I may shew thee the word of God."}, {"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}], [{"ref": "1 Samuel 16:13", "text": "Then Samuel took the horn of oil, and anointed him in the midst of his brethren: and the Spirit of the LORD came upon David from that day forward. So Samuel rose up, and went to Ramah."}]]'::jsonb, updated_at = now() where id = 'seq-samuel' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 7:58-60", "text": "And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul. And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit. And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep."}, {"ref": "Acts 8:1", "text": "And Saul was consenting unto his death. And at that time there was a great persecution against the church which was at Jerusalem; and they were all scattered abroad throughout the regions of Judæa and Samaria, except the apostles."}], [{"ref": "Acts 9:1-3", "text": "And Saul, yet breathing out threatenings and slaughter against the disciples of the Lord, went unto the high priest, And desired of him letters to Damascus to the synagogues, that if he found any of this way, whether they were men or women, he might bring them bound unto Jerusalem. And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven:"}], [{"ref": "Acts 9:8-9", "text": "And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him by the hand, and brought him into Damascus. And he was three days without sight, and neither did eat nor drink."}], [{"ref": "Acts 9:17", "text": "And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost."}], [{"ref": "Acts 9:19-20", "text": "And when he had received meat, he was strengthened. Then was Saul certain days with the disciples which were at Damascus. And straightway he preached Christ in the synagogues, that he is the Son of God."}]]'::jsonb, updated_at = now() where id = 'seq-saul_conversion' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 8:4-5", "text": "Then all the elders of Israel gathered themselves together, and came to Samuel unto Ramah, And said unto him, Behold, thou art old, and thy sons walk not in thy ways: now make us a king to judge us like all the nations."}], [{"ref": "1 Samuel 9:1-2", "text": "Now there was a man of Benjamin, whose name was Kish, the son of Abiel, the son of Zeror, the son of Bechorath, the son of Aphiah, a Benjamite, a mighty man of power. And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people."}], [{"ref": "1 Samuel 9:27", "text": "And as they were going down to the end of the city, Samuel said to Saul, Bid the servant pass on before us, (and he passed on,) but stand thou still a while, that I may shew thee the word of God."}, {"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}], [{"ref": "1 Samuel 10:21-24", "text": "When he had caused the tribe of Benjamin to come near by their families, the family of Matri was taken, and Saul the son of Kish was taken: and when they sought him, he could not be found. Therefore they enquired of the LORD further, if the man should yet come thither. And the LORD answered, Behold, he hath hid himself among the stuff. And they ran and fetched him thence: and when he stood among the people, he was higher than any of the people from his shoulders and upward. And Samuel said to all the people, See ye him whom the LORD hath chosen, that there is none like him among all the people? And all the people shouted, and said, God save the king."}], [{"ref": "1 Samuel 15:22-23", "text": "And Samuel said, Hath the LORD as great delight in burnt offerings and sacrifices, as in obeying the voice of the LORD? Behold, to obey is better than sacrifice, and to hearken than the fat of rams. For rebellion is as the sin of witchcraft, and stubbornness is as iniquity and idolatry. Because thou hast rejected the word of the LORD, he hath also rejected thee from being king."}]]'::jsonb, updated_at = now() where id = 'seq-saul_king' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 19:2", "text": "For they were departed from Rephidim, and were come to the desert of Sinai, and had pitched in the wilderness; and there Israel camped before the mount."}], [{"ref": "Exodus 19:18", "text": "And mount Sinai was altogether on a smoke, because the LORD descended upon it in fire: and the smoke thereof ascended as the smoke of a furnace, and the whole mount quaked greatly."}], [{"ref": "Exodus 20:1-3", "text": "And God spake all these words, saying, I am the LORD thy God, which have brought thee out of the land of Egypt, out of the house of bondage. Thou shalt have no other gods before me."}, {"ref": "Deuteronomy 4:13", "text": "And he declared unto you his covenant, which he commanded you to perform, even ten commandments; and he wrote them upon two tables of stone."}], [{"ref": "Exodus 32:1-4", "text": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him. And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me. And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron. And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt."}], [{"ref": "Exodus 34:1-4", "text": "And the LORD said unto Moses, Hew thee two tables of stone like unto the first: and I will write upon these tables the words that were in the first tables, which thou brakest. And be ready in the morning, and come up in the morning unto mount Sinai, and present thyself there to me in the top of the mount. And no man shall come up with thee, neither let any man be seen throughout all the mount; neither let the flocks nor herds feed before that mount. And he hewed two tables of stone like unto the first; and Moses rose up early in the morning, and went up unto mount Sinai, as the LORD had commanded him, and took in his hand the two tables of stone."}]]'::jsonb, updated_at = now() where id = 'seq-sinai' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "1 Kings 3:9", "text": "Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?"}], [{"ref": "1 Kings 3:16-17", "text": "Then came there two women, that were harlots, unto the king, and stood before him. And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house."}, {"ref": "1 Kings 3:24-27", "text": "And the king said, Bring me a sword. And they brought a sword before the king. And the king said, Divide the living child in two, and give half to the one, and half to the other. Then spake the woman whose the living child was unto the king, for her bowels yearned upon her son, and she said, O my lord, give her the living child, and in no wise slay it. But the other said, Let it be neither mine nor thine, but divide it. Then the king answered and said, Give her the living child, and in no wise slay it: she is the mother thereof."}], [{"ref": "1 Kings 6:1", "text": "And it came to pass in the four hundred and eightieth year after the children of Israel were come out of the land of Egypt, in the fourth year of Solomon’s reign over Israel, in the month Zif, which is the second month, that he began to build the house of the LORD."}, {"ref": "1 Kings 6:14", "text": "So Solomon built the house, and finished it."}], [{"ref": "1 Kings 8:63", "text": "And Solomon offered a sacrifice of peace offerings, which he offered unto the LORD, two and twenty thousand oxen, and an hundred and twenty thousand sheep. So the king and all the children of Israel dedicated the house of the LORD."}], [{"ref": "1 Kings 10:1-2", "text": "And when the queen of Sheba heard of the fame of Solomon concerning the name of the LORD, she came to prove him with hard questions. And she came to Jerusalem with a very great train, with camels that bare spices, and very much gold, and precious stones: and when she was come to Solomon, she communed with him of all that was in her heart."}]]'::jsonb, updated_at = now() where id = 'seq-solomon' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Acts 6:3-5", "text": "Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business. But we will give ourselves continually to prayer, and to the ministry of the word. And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:"}], [{"ref": "Acts 6:8", "text": "And Stephen, full of faith and power, did great wonders and miracles among the people."}], [{"ref": "Acts 6:9-12", "text": "Then there arose certain of the synagogue, which is called the synagogue of the Libertines, and Cyrenians, and Alexandrians, and of them of Cilicia and of Asia, disputing with Stephen. And they were not able to resist the wisdom and the spirit by which he spake. Then they suborned men, which said, We have heard him speak blasphemous words against Moses, and against God. And they stirred up the people, and the elders, and the scribes, and came upon him, and caught him, and brought him to the council,"}], [{"ref": "Acts 7:55-56", "text": "But he, being full of the Holy Ghost, looked up stedfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God, And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God."}], [{"ref": "Acts 7:59-60", "text": "And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit. And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep."}]]'::jsonb, updated_at = now() where id = 'seq-stephen' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Numbers 13:17", "text": "And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:"}], [{"ref": "Numbers 13:23", "text": "And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs."}], [{"ref": "Numbers 13:30", "text": "And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it."}], [{"ref": "Numbers 14:2", "text": "And all the children of Israel murmured against Moses and against Aaron: and the whole congregation said unto them, Would God that we had died in the land of Egypt! or would God we had died in this wilderness!"}], [{"ref": "Numbers 14:33-34", "text": "And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness. After the number of the days in which ye searched the land, even forty days, each day for a year, shall ye bear your iniquities, even forty years, and ye shall know my breach of promise."}]]'::jsonb, updated_at = now() where id = 'seq-twelve_spies' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Matthew 14:23", "text": "And when he had sent the multitudes away, he went up into a mountain apart to pray: and when the evening was come, he was there alone."}], [{"ref": "Matthew 14:24", "text": "But the ship was now in the midst of the sea, tossed with waves: for the wind was contrary."}], [{"ref": "Matthew 14:25", "text": "And in the fourth watch of the night Jesus went unto them, walking on the sea."}], [{"ref": "Matthew 14:28-30", "text": "And Peter answered him and said, Lord, if it be thou, bid me come unto thee on the water. And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus. But when he saw the wind boisterous, he was afraid; and beginning to sink, he cried, saying, Lord, save me."}], [{"ref": "Matthew 14:32", "text": "And when they were come into the ship, the wind ceased."}]]'::jsonb, updated_at = now() where id = 'seq-walking_water' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 16:14-15", "text": "And when the dew that lay was gone up, behold, upon the face of the wilderness there lay a small round thing, as small as the hoar frost on the ground. And when the children of Israel saw it, they said one to another, It is manna: for they wist not what it was. And Moses said unto them, This is the bread which the LORD hath given you to eat."}], [{"ref": "Exodus 19:20", "text": "And the LORD came down upon mount Sinai, on the top of the mount: and the LORD called Moses up to the top of the mount; and Moses went up."}, {"ref": "Exodus 20:1-3", "text": "And God spake all these words, saying, I am the LORD thy God, which have brought thee out of the land of Egypt, out of the house of bondage. Thou shalt have no other gods before me."}], [{"ref": "Exodus 32:1-4", "text": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him. And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me. And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron. And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt."}], [{"ref": "Numbers 13:1-3", "text": "And the LORD spake unto Moses, saying, Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them. And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel."}, {"ref": "Numbers 13:17", "text": "And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:"}]]'::jsonb, updated_at = now() where id = 'seq-wilderness' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Luke 19:2-3", "text": "And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature."}], [{"ref": "Luke 19:4", "text": "And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way."}], [{"ref": "Luke 19:5", "text": "And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchæus, make haste, and come down; for to day I must abide at thy house."}], [{"ref": "Luke 19:7", "text": "And when they saw it, they all murmured, saying, That he was gone to be guest with a man that is a sinner."}], [{"ref": "Luke 19:8", "text": "And Zacchæus stood, and said unto the Lord; Behold, Lord, the half of my goods I give to the poor; and if I have taken any thing from any man by false accusation, I restore him fourfold."}]]'::jsonb, updated_at = now() where id = 'seq-zacchaeus' and game_mode = 'sequence';
update public.questions set clue_refs = '[[{"ref": "Exodus 4:14", "text": "And the anger of the LORD was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart."}], [{"ref": "Exodus 7:2", "text": "Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land."}], [{"ref": "Exodus 32:1-4", "text": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him. And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me. And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron. And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt."}], [{"ref": "Numbers 17:8", "text": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}]]'::jsonb, updated_at = now() where id = 'who-aaron' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:4", "text": "And Abel, he also brought of the firstlings of his flock and of the fat thereof. And the LORD had respect unto Abel and to his offering:"}], [{"ref": "Genesis 4:8", "text": "And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him."}]]'::jsonb, updated_at = now() where id = 'who-abel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 25:3", "text": "Now the name of the man was Nabal; and the name of his wife Abigail: and she was a woman of good understanding, and of a beautiful countenance: but the man was churlish and evil in his doings; and he was of the house of Caleb."}], [{"ref": "1 Samuel 25:18", "text": "Then Abigail made haste, and took two hundred loaves, and two bottles of wine, and five sheep ready dressed, and five measures of parched corn, and an hundred clusters of raisins, and two hundred cakes of figs, and laid them on asses."}], [{"ref": "1 Samuel 25:33", "text": "And blessed be thy advice, and blessed be thou, which hast kept me this day from coming to shed blood, and from avenging myself with mine own hand."}], [{"ref": "1 Samuel 25:38-39", "text": "And it came to pass about ten days after, that the LORD smote Nabal, that he died. And when David heard that Nabal was dead, he said, Blessed be the LORD, that hath pleaded the cause of my reproach from the hand of Nabal, and hath kept his servant from evil: for the LORD hath returned the wickedness of Nabal upon his own head. And David sent and communed with Abigail, to take her to him to wife."}, {"ref": "1 Samuel 25:42", "text": "And Abigail hasted, and arose, and rode upon an ass, with five damsels of hers that went after her; and she went after the messengers of David, and became his wife."}]]'::jsonb, updated_at = now() where id = 'who-abigail' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 11:31", "text": "And Terah took Abram his son, and Lot the son of Haran his son’s son, and Sarai his daughter in law, his son Abram’s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there."}], [{"ref": "Genesis 17:5", "text": "Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee."}], [{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 22:1-2", "text": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}]]'::jsonb, updated_at = now() where id = 'who-abraham' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 3:3", "text": "And his second, Chileab, of Abigail the wife of Nabal the Carmelite; and the third, Absalom the son of Maacah the daughter of Talmai king of Geshur;"}], [{"ref": "2 Samuel 15:6", "text": "And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel."}], [{"ref": "2 Samuel 15:10-12", "text": "But Absalom sent spies throughout all the tribes of Israel, saying, As soon as ye hear the sound of the trumpet, then ye shall say, Absalom reigneth in Hebron. And with Absalom went two hundred men out of Jerusalem, that were called; and they went in their simplicity, and they knew not any thing. And Absalom sent for Ahithophel the Gilonite, David’s counsellor, from his city, even from Giloh, while he offered sacrifices. And the conspiracy was strong; for the people increased continually with Absalom."}], [{"ref": "2 Samuel 18:9", "text": "And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away."}]]'::jsonb, updated_at = now() where id = 'who-absalom' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Joshua 7:1", "text": "But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the LORD was kindled against the children of Israel."}, {"ref": "Joshua 7:21", "text": "When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."}], [{"ref": "Joshua 7:21", "text": "When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."}], [{"ref": "Joshua 7:4-5", "text": "So there went up thither of the people about three thousand men: and they fled before the men of Ai. And the men of Ai smote of them about thirty and six men: for they chased them from before the gate even unto Shebarim, and smote them in the going down: wherefore the hearts of the people melted, and became as water."}, {"ref": "Joshua 7:11-12", "text": "Israel hath sinned, and they have also transgressed my covenant which I commanded them: for they have even taken of the accursed thing, and have also stolen, and dissembled also, and they have put it even among their own stuff. Therefore the children of Israel could not stand before their enemies, but turned their backs before their enemies, because they were accursed: neither will I be with you any more, except ye destroy the accursed from among you."}], [{"ref": "Joshua 7:1", "text": "But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the LORD was kindled against the children of Israel."}]]'::jsonb, updated_at = now() where id = 'who-achan' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 2:7", "text": "And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul."}], [{"ref": "Genesis 2:20", "text": "And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him."}], [{"ref": "Genesis 2:15", "text": "And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it."}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb, updated_at = now() where id = 'who-adam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 25:13", "text": "And after certain days king Agrippa and Bernice came unto Cæsarea to salute Festus."}], [{"ref": "Acts 25:14", "text": "And when they had been there many days, Festus declared Paul’s cause unto the king, saying, There is a certain man left in bonds by Felix:"}], [{"ref": "Acts 26:1-2", "text": "Then Agrippa said unto Paul, Thou art permitted to speak for thyself. Then Paul stretched forth the hand, and answered for himself: I think myself happy, king Agrippa, because I shall answer for myself this day before thee touching all the things whereof I am accused of the Jews:"}], [{"ref": "Acts 26:28", "text": "Then Agrippa said unto Paul, Almost thou persuadest me to be a Christian."}]]'::jsonb, updated_at = now() where id = 'who-agrippa' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 16:29", "text": "And in the thirty and eighth year of Asa king of Judah began Ahab the son of Omri to reign over Israel: and Ahab the son of Omri reigned over Israel in Samaria twenty and two years."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 18:17", "text": "And it came to pass, when Ahab saw Elijah, that Ahab said unto him, Art thou he that troubleth Israel?"}], [{"ref": "1 Kings 21:2", "text": "And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money."}]]'::jsonb, updated_at = now() where id = 'who-ahab' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Amos 1:1", "text": "The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 5:24", "text": "But let judgment run down as waters, and righteousness as a mighty stream."}]]'::jsonb, updated_at = now() where id = 'who-amos' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 9:10", "text": "And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord."}], [{"ref": "Acts 9:10-12", "text": "And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord. And the Lord said unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth, And hath seen in a vision a man named Ananias coming in, and putting his hand on him, that he might receive his sight."}], [{"ref": "Acts 9:13", "text": "Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:"}], [{"ref": "Acts 9:17", "text": "And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost."}]]'::jsonb, updated_at = now() where id = 'who-ananias' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:40", "text": "One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother."}], [{"ref": "John 1:41-42", "text": "He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ. And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone."}], [{"ref": "John 6:8-9", "text": "One of his disciples, Andrew, Simon Peter’s brother, saith unto him, There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"}]]'::jsonb, updated_at = now() where id = 'who-andrew' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:36", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;"}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:27", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law,"}, {"ref": "Luke 2:36-38", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity; And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day. And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem."}]]'::jsonb, updated_at = now() where id = 'who-anna' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}], [{"ref": "1 Corinthians 3:6", "text": "I have planted, Apollos watered; but God gave the increase."}]]'::jsonb, updated_at = now() where id = 'who-apollos' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Joshua 13:22", "text": "Balaam also the son of Beor, the soothsayer, did the children of Israel slay with the sword among them that were slain by them."}], [{"ref": "Numbers 22:4-6", "text": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time. He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me: Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou blessest is blessed, and he whom thou cursest is cursed."}], [{"ref": "Numbers 22:31", "text": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}], [{"ref": "Numbers 22:28", "text": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}]]'::jsonb, updated_at = now() where id = 'who-balaam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 27:15-16", "text": "Now at that feast the governor was wont to release unto the people a prisoner, whom they would. And they had then a notable prisoner, called Barabbas."}], [{"ref": "Mark 15:7", "text": "And there was one named Barabbas, which lay bound with them that had made insurrection with him, who had committed murder in the insurrection."}], [{"ref": "Matthew 27:17", "text": "Therefore when they were gathered together, Pilate said unto them, Whom will ye that I release unto you? Barabbas, or Jesus which is called Christ?"}], [{"ref": "Mark 15:11", "text": "But the chief priests moved the people, that he should rather release Barabbas unto them."}]]'::jsonb, updated_at = now() where id = 'who-barabbas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 4:6", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun?"}], [{"ref": "Judges 4:8", "text": "And Barak said unto her, If thou wilt go with me, then I will go: but if thou wilt not go with me, then I will not go."}], [{"ref": "Judges 4:14", "text": "And Deborah said unto Barak, Up; for this is the day in which the LORD hath delivered Sisera into thine hand: is not the LORD gone out before thee? So Barak went down from mount Tabor, and ten thousand men after him."}], [{"ref": "Judges 4:7", "text": "And I will draw unto thee to the river Kishon Sisera, the captain of Jabin’s army, with his chariots and his multitude; and I will deliver him into thine hand."}, {"ref": "Judges 4:15", "text": "And the LORD discomfited Sisera, and all his chariots, and all his host, with the edge of the sword before Barak; so that Sisera lighted down off his chariot, and fled away on his feet."}]]'::jsonb, updated_at = now() where id = 'who-barak' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 4:36", "text": "And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,"}], [{"ref": "Acts 4:37", "text": "Having land, sold it, and brought the money, and laid it at the apostles’ feet."}], [{"ref": "Acts 9:26-27", "text": "And when Saul was come to Jerusalem, he assayed to join himself to the disciples: but they were all afraid of him, and believed not that he was a disciple. But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus."}], [{"ref": "Acts 13:2-4", "text": "As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them. And when they had fasted and prayed, and laid their hands on them, they sent them away. So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus."}]]'::jsonb, updated_at = now() where id = 'who-barnabas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Mark 10:46", "text": "And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimæus, the son of Timæus, sat by the highway side begging."}], [{"ref": "Mark 10:47", "text": "And when he heard that it was Jesus of Nazareth, he began to cry out, and say, Jesus, thou Son of David, have mercy on me."}], [{"ref": "Mark 10:48", "text": "And many charged him that he should hold his peace: but he cried the more a great deal, Thou Son of David, have mercy on me."}], [{"ref": "Mark 10:50-52", "text": "And he, casting away his garment, rose, and came to Jesus. And Jesus answered and said unto him, What wilt thou that I should do unto thee? The blind man said unto him, Lord, that I might receive my sight. And Jesus said unto him, Go thy way; thy faith hath made thee whole. And immediately he received his sight, and followed Jesus in the way."}]]'::jsonb, updated_at = now() where id = 'who-bartimaeus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}], [{"ref": "2 Samuel 11:2", "text": "And it came to pass in an eveningtide, that David arose from off his bed, and walked upon the roof of the king’s house: and from the roof he saw a woman washing herself; and the woman was very beautiful to look upon."}], [{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 2:19", "text": "Bath-sheba therefore went unto king Solomon, to speak unto him for Adonijah. And the king rose up to meet her, and bowed himself unto her, and sat down on his throne, and caused a seat to be set for the king’s mother; and she sat on his right hand."}]]'::jsonb, updated_at = now() where id = 'who-bathsheba' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Daniel 5:1", "text": "Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand."}, {"ref": "Daniel 5:30", "text": "In that night was Belshazzar the king of the Chaldeans slain."}], [{"ref": "Daniel 5:3", "text": "Then they brought the golden vessels that were taken out of the temple of the house of God which was at Jerusalem; and the king, and his princes, his wives, and his concubines, drank in them."}], [{"ref": "Daniel 5:5", "text": "In the same hour came forth fingers of a man’s hand, and wrote over against the candlestick upon the plaister of the wall of the king’s palace: and the king saw the part of the hand that wrote."}], [{"ref": "Daniel 5:30", "text": "In that night was Belshazzar the king of the Chaldeans slain."}]]'::jsonb, updated_at = now() where id = 'who-belshazzar' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 42:4", "text": "But Benjamin, Joseph’s brother, Jacob sent not with his brethren; for he said, Lest peradventure mischief befall him."}, {"ref": "Genesis 42:13", "text": "And they said, Thy servants are twelve brethren, the sons of one man in the land of Canaan; and, behold, the youngest is this day with our father, and one is not."}], [{"ref": "Genesis 35:18", "text": "And it came to pass, as her soul was in departing, (for she died) that she called his name Ben-oni: but his father called him Benjamin."}], [{"ref": "Genesis 44:2", "text": "And put my cup, the silver cup, in the sack’s mouth of the youngest, and his corn money. And he did according to the word that Joseph had spoken."}, {"ref": "Genesis 44:12", "text": "And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin’s sack."}], [{"ref": "Genesis 35:24", "text": "The sons of Rachel; Joseph, and Benjamin:"}]]'::jsonb, updated_at = now() where id = 'who-benjamin' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ruth 2:1", "text": "And Naomi had a kinsman of her husband’s, a mighty man of wealth, of the family of Elimelech; and his name was Boaz."}, {"ref": "Ruth 2:4", "text": "And, behold, Boaz came from Beth-lehem, and said unto the reapers, The LORD be with you. And they answered him, The LORD bless thee."}], [{"ref": "Ruth 2:6", "text": "And the servant that was set over the reapers answered and said, It is the Moabitish damsel that came back with Naomi out of the country of Moab:"}, {"ref": "Ruth 2:8", "text": "Then said Boaz unto Ruth, Hearest thou not, my daughter? Go not to glean in another field, neither go from hence, but abide here fast by my maidens:"}], [{"ref": "Ruth 4:9-10", "text": "And Boaz said unto the elders, and unto all the people, Ye are witnesses this day, that I have bought all that was Elimelech’s, and all that was Chilion’s and Mahlon’s, of the hand of Naomi. Moreover Ruth the Moabitess, the wife of Mahlon, have I purchased to be my wife, to raise up the name of the dead upon his inheritance, that the name of the dead be not cut off from among his brethren, and from the gate of his place: ye are witnesses this day."}], [{"ref": "Ruth 4:13", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son."}]]'::jsonb, updated_at = now() where id = 'who-boaz' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:49", "text": "And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all,"}], [{"ref": "John 11:50", "text": "Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not."}], [{"ref": "John 18:13", "text": "And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}], [{"ref": "John 18:24", "text": "Now Annas had sent him bound unto Caiaphas the high priest."}]]'::jsonb, updated_at = now() where id = 'who-caiaphas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:5", "text": "But unto Cain and to his offering he had not respect. And Cain was very wroth, and his countenance fell."}], [{"ref": "Genesis 4:9", "text": "And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?"}], [{"ref": "Genesis 4:15", "text": "And the LORD said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the LORD set a mark upon Cain, lest any finding him should kill him."}]]'::jsonb, updated_at = now() where id = 'who-cain' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Numbers 13:6", "text": "Of the tribe of Judah, Caleb the son of Jephunneh."}], [{"ref": "Numbers 14:6-9", "text": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes: And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land. If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey. Only rebel not ye against the LORD, neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not."}], [{"ref": "Joshua 14:10", "text": "And now, behold, the LORD hath kept me alive, as he said, these forty and five years, even since the LORD spake this word unto Moses, while the children of Israel wandered in the wilderness: and now, lo, I am this day fourscore and five years old."}], [{"ref": "Joshua 14:12-13", "text": "Now therefore give me this mountain, whereof the LORD spake in that day; for thou heardest in that day how the Anakims were there, and that the cities were great and fenced: if so be the LORD will be with me, then I shall be able to drive them out, as the LORD said. And Joshua blessed him, and gave unto Caleb the son of Jephunneh Hebron for an inheritance."}]]'::jsonb, updated_at = now() where id = 'who-caleb' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 10:1", "text": "There was a certain man in Cæsarea called Cornelius, a centurion of the band called the Italian band,"}], [{"ref": "Acts 10:2", "text": "A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway."}], [{"ref": "Acts 10:3-5", "text": "He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius. And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God. And now send men to Joppa, and call for one Simon, whose surname is Peter:"}], [{"ref": "Acts 10:24", "text": "And the morrow after they entered into Cæsarea. And Cornelius waited for them, and had called together his kinsmen and near friends."}, {"ref": "Acts 10:44", "text": "While Peter yet spake these words, the Holy Ghost fell on all them which heard the word."}]]'::jsonb, updated_at = now() where id = 'who-cornelius' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ezra 1:1", "text": "Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}], [{"ref": "Ezra 1:1", "text": "Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}], [{"ref": "Ezra 1:2-3", "text": "Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah. Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the LORD God of Israel, (he is the God,) which is in Jerusalem."}], [{"ref": "Isaiah 45:1", "text": "Thus saith the LORD to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;"}]]'::jsonb, updated_at = now() where id = 'who-cyrus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Daniel 1:1-6", "text": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it. And the Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God: which he carried into the land of Shinar to the house of his god; and he brought the vessels into the treasure house of his god. And the king spake unto Ashpenaz the master of his eunuchs, that he should bring certain of the children of Israel, and of the king’s seed, and of the princes; Children in whom was no blemish, but well favoured, and skilful in all wisdom, and cunning in knowledge, and understanding science, and such as had ability in them to stand in the king’s palace, and whom they might teach the learning and the tongue of the Chaldeans. And the king appointed them a daily provision of the king’s meat, and of the wine which he drank: so nourishing them three years, that at the end thereof they might stand before the king. Now among these were of the children of Judah, Daniel, Hananiah, Mishael, and Azariah:"}], [{"ref": "Daniel 1:8", "text": "But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."}], [{"ref": "Daniel 5:25-28", "text": "And this is the writing that was written, MENE, MENE, TEKEL, UPHARSIN. This is the interpretation of the thing: MENE; God hath numbered thy kingdom, and finished it. TEKEL; Thou art weighed in the balances, and art found wanting. PERES; Thy kingdom is divided, and given to the Medes and Persians."}], [{"ref": "Daniel 6:22-23", "text": "My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt. Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God."}]]'::jsonb, updated_at = now() where id = 'who-daniel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 16:11", "text": "And Samuel said unto Jesse, Are here all thy children? And he said, There remaineth yet the youngest, and, behold, he keepeth the sheep. And Samuel said unto Jesse, Send and fetch him: for we will not sit down till he come hither."}], [{"ref": "1 Samuel 16:23", "text": "And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him."}], [{"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}], [{"ref": "2 Samuel 5:3", "text": "So all the elders of Israel came to the king to Hebron; and king David made a league with them in Hebron before the LORD: and they anointed David king over Israel."}]]'::jsonb, updated_at = now() where id = 'who-david' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 4:4", "text": "And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time."}], [{"ref": "Judges 4:5", "text": "And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment."}], [{"ref": "Judges 4:6-7", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun? And I will draw unto thee to the river Kishon Sisera, the captain of Jabin’s army, with his chariots and his multitude; and I will deliver him into thine hand."}], [{"ref": "Judges 5:1", "text": "Then sang Deborah and Barak the son of Abinoam on that day, saying,"}]]'::jsonb, updated_at = now() where id = 'who-deborah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 16:4", "text": "And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."}], [{"ref": "Judges 16:5", "text": "And the lords of the Philistines came up unto her, and said unto her, Entice him, and see wherein his great strength lieth, and by what means we may prevail against him, that we may bind him to afflict him: and we will give thee every one of us eleven hundred pieces of silver."}], [{"ref": "Judges 16:6", "text": "And Delilah said to Samson, Tell me, I pray thee, wherein thy great strength lieth, and wherewith thou mightest be bound to afflict thee."}], [{"ref": "Judges 16:19", "text": "And she made him sleep upon her knees; and she called for a man, and she caused him to shave off the seven locks of his head; and she began to afflict him, and his strength went from him."}]]'::jsonb, updated_at = now() where id = 'who-delilah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:39", "text": "Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them."}], [{"ref": "Acts 9:40", "text": "But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up."}]]'::jsonb, updated_at = now() where id = 'who-dorcas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 3:15", "text": "But when the children of Israel cried unto the LORD, the LORD raised them up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded: and by him the children of Israel sent a present unto Eglon the king of Moab."}], [{"ref": "Judges 3:15", "text": "But when the children of Israel cried unto the LORD, the LORD raised them up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded: and by him the children of Israel sent a present unto Eglon the king of Moab."}], [{"ref": "Judges 3:16", "text": "But Ehud made him a dagger which had two edges, of a cubit length; and he did gird it under his raiment upon his right thigh."}], [{"ref": "Judges 3:17", "text": "And he brought the present unto Eglon king of Moab: and Eglon was a very fat man."}, {"ref": "Judges 3:21", "text": "And Ehud put forth his left hand, and took the dagger from his right thigh, and thrust it into his belly:"}, {"ref": "Judges 3:25", "text": "And they tarried till they were ashamed: and, behold, he opened not the doors of the parlour; therefore they took a key, and opened them: and, behold, their lord was fallen down dead on the earth."}]]'::jsonb, updated_at = now() where id = 'who-ehud' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD."}], [{"ref": "1 Samuel 1:13-14", "text": "Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken. And Eli said unto her, How long wilt thou be drunken? put away thy wine from thee."}], [{"ref": "1 Samuel 1:3", "text": "And this man went up out of his city yearly to worship and to sacrifice unto the LORD of hosts in Shiloh. And the two sons of Eli, Hophni and Phinehas, the priests of the LORD, were there."}, {"ref": "1 Samuel 2:12", "text": "Now the sons of Eli were sons of Belial; they knew not the LORD."}], [{"ref": "1 Samuel 4:17-18", "text": "And the messenger answered and said, Israel is fled before the Philistines, and there hath been also a great slaughter among the people, and thy two sons also, Hophni and Phinehas, are dead, and the ark of God is taken. And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."}]]'::jsonb, updated_at = now() where id = 'who-eli' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 17:1", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word."}], [{"ref": "1 Kings 17:1-6", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook."}], [{"ref": "1 Kings 18:19-24", "text": "Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table. So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel. And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word. Then said Elijah unto the people, I, even I only, remain a prophet of the LORD; but Baal’s prophets are four hundred and fifty men. Let them therefore give us two bullocks; and let them choose one bullock for themselves, and cut it in pieces, and lay it on wood, and put no fire under: and I will dress the other bullock, and lay it on wood, and put no fire under: And call ye on the name of your gods, and I will call on the name of the LORD: and the God that answereth by fire, let him be God. And all the people answered and said, It is well spoken."}], [{"ref": "2 Kings 2:11", "text": "And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven."}]]'::jsonb, updated_at = now() where id = 'who-elijah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}], [{"ref": "Luke 1:7", "text": "And they had no child, because that Elisabeth was barren, and they both were now well stricken in years."}], [{"ref": "Luke 1:41", "text": "And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:"}], [{"ref": "Luke 1:57-60", "text": "Now Elisabeth’s full time came that she should be delivered; and she brought forth a son. And her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her. And it came to pass, that on the eighth day they came to circumcise the child; and they called him Zacharias, after the name of his father. And his mother answered and said, Not so; but he shall be called John."}]]'::jsonb, updated_at = now() where id = 'who-elisabeth' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 19:19", "text": "So he departed thence, and found Elisha the son of Shaphat, who was plowing with twelve yoke of oxen before him, and he with the twelfth: and Elijah passed by him, and cast his mantle upon him."}], [{"ref": "2 Kings 2:9", "text": "And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."}], [{"ref": "2 Kings 2:13", "text": "He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;"}], [{"ref": "2 Kings 5:10", "text": "And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean."}]]'::jsonb, updated_at = now() where id = 'who-elisha' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 5:22", "text": "And Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters:"}], [{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:24", "text": "And Enoch walked with God: and he was not; for God took him."}], [{"ref": "Hebrews 11:5", "text": "By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God."}]]'::jsonb, updated_at = now() where id = 'who-enoch' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 25:27", "text": "And the boys grew: and Esau was a cunning hunter, a man of the field; and Jacob was a plain man, dwelling in tents."}], [{"ref": "Genesis 25:25", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 36:1", "text": "Now these are the generations of Esau, who is Edom."}]]'::jsonb, updated_at = now() where id = 'who-esau' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Esther 2:7", "text": "And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}], [{"ref": "Esther 1:3", "text": "In the third year of his reign, he made a feast unto all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him:"}, {"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}], [{"ref": "Esther 4:16", "text": "Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish."}], [{"ref": "Esther 9:22", "text": "As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor."}, {"ref": "Esther 9:26-28", "text": "Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them, The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their appointed time every year; And that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed."}]]'::jsonb, updated_at = now() where id = 'who-esther' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 20:6", "text": "And we sailed away from Philippi after the days of unleavened bread, and came unto them to Troas in five days; where we abode seven days."}, {"ref": "Acts 20:9", "text": "And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:7-9", "text": "And upon the first day of the week, when the disciples came together to break bread, Paul preached unto them, ready to depart on the morrow; and continued his speech until midnight. And there were many lights in the upper chamber, where they were gathered together. And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:9", "text": "And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:10-12", "text": "And Paul went down, and fell on him, and embracing him said, Trouble not yourselves; for his life is in him. When he therefore was come up again, and had broken bread, and eaten, and talked a long while, even till break of day, so he departed. And they brought the young man alive, and were not a little comforted."}]]'::jsonb, updated_at = now() where id = 'who-eutychus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 3:1", "text": "Now the serpent was more subtil than any beast of the field which the LORD God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?"}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb, updated_at = now() where id = 'who-eve' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ezekiel 1:1-3", "text": "Now it came to pass in the thirtieth year, in the fourth month, in the fifth day of the month, as I was among the captives by the river of Chebar, that the heavens were opened, and I saw visions of God. In the fifth day of the month, which was the fifth year of king Jehoiachin’s captivity, The word of the LORD came expressly unto Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the river Chebar; and the hand of the LORD was there upon him."}], [{"ref": "Ezekiel 1:18", "text": "As for their rings, they were so high that they were dreadful; and their rings were full of eyes round about them four."}], [{"ref": "Ezekiel 4:4-6", "text": "Lie thou also upon thy left side, and lay the iniquity of the house of Israel upon it: according to the number of the days that thou shalt lie upon it thou shalt bear their iniquity. For I have laid upon thee the years of their iniquity, according to the number of the days, three hundred and ninety days: so shalt thou bear the iniquity of the house of Israel. And when thou hast accomplished them, lie again on thy right side, and thou shalt bear the iniquity of the house of Judah forty days: I have appointed thee each day for a year."}], [{"ref": "Ezekiel 37:4", "text": "Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-ezekiel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ezra 7:6", "text": "This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}, {"ref": "Ezra 7:11", "text": "Now this is the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, even a scribe of the words of the commandments of the LORD, and of his statutes to Israel."}], [{"ref": "Ezra 7:1-6", "text": "Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah, The son of Shallum, the son of Zadok, the son of Ahitub, The son of Amariah, the son of Azariah, the son of Meraioth, The son of Zerahiah, the son of Uzzi, the son of Bukki, The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest: This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}], [{"ref": "Nehemiah 8:2-3", "text": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month. And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}], [{"ref": "Nehemiah 8:4", "text": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}]]'::jsonb, updated_at = now() where id = 'who-ezra' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:38", "text": "And now I say unto you, Refrain from these men, and let them alone: for if this counsel or this work be of men, it will come to nought:"}], [{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}]]'::jsonb, updated_at = now() where id = 'who-gamaliel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 4:12", "text": "And he said to Gehazi his servant, Call this Shunammite. And when he had called her, she stood before him."}], [{"ref": "2 Kings 4:14", "text": "And he said, What then is to be done for her? And Gehazi answered, Verily she hath no child, and her husband is old."}], [{"ref": "2 Kings 5:20-23", "text": "But Gehazi, the servant of Elisha the man of God, said, Behold, my master hath spared Naaman this Syrian, in not receiving at his hands that which he brought: but, as the LORD liveth, I will run after him, and take somewhat of him. So Gehazi followed after Naaman. And when Naaman saw him running after him, he lighted down from the chariot to meet him, and said, Is all well? And he said, All is well. My master hath sent me, saying, Behold, even now there be come to me from mount Ephraim two young men of the sons of the prophets: give them, I pray thee, a talent of silver, and two changes of garments. And Naaman said, Be content, take two talents. And he urged him, and bound two talents of silver in two bags, with two changes of garments, and laid them upon two of his servants; and they bare them before him."}], [{"ref": "2 Kings 5:27", "text": "The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow."}]]'::jsonb, updated_at = now() where id = 'who-gehazi' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 6:11-12", "text": "And there came an angel of the LORD, and sat under an oak which was in Ophrah, that pertained unto Joash the Abi-ezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites. And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour."}], [{"ref": "Judges 6:36-40", "text": "And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said, Behold, I will put a fleece of wool in the floor; and if the dew be on the fleece only, and it be dry upon all the earth beside, then shall I know that thou wilt save Israel by mine hand, as thou hast said. And it was so: for he rose up early on the morrow, and thrust the fleece together, and wringed the dew out of the fleece, a bowl full of water. And Gideon said unto God, Let not thine anger be hot against me, and I will speak but this once: let me prove, I pray thee, but this once with the fleece; let it now be dry only upon the fleece, and upon all the ground let there be dew. And God did so that night: for it was dry upon the fleece only, and there was dew on all the ground."}], [{"ref": "Judges 7:7", "text": "And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place."}], [{"ref": "Judges 7:16", "text": "And he divided the three hundred men into three companies, and he put a trumpet in every man’s hand, with empty pitchers, and lamps within the pitchers."}]]'::jsonb, updated_at = now() where id = 'who-gideon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:15", "text": "But David went and returned from Saul to feed his father’s sheep at Beth-lehem."}, {"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}]]'::jsonb, updated_at = now() where id = 'who-goliath' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 16:1", "text": "Now Sarai Abram’s wife bare him no children: and she had an handmaid, an Egyptian, whose name was Hagar."}], [{"ref": "Genesis 16:6-7", "text": "But Abram said unto Sarai, Behold, thy maid is in thy hand; do to her as it pleaseth thee. And when Sarai dealt hardly with her, she fled from her face. And the angel of the LORD found her by a fountain of water in the wilderness, by the fountain in the way to Shur."}], [{"ref": "Genesis 16:13", "text": "And she called the name of the LORD that spake unto her, Thou God seest me: for she said, Have I also here looked after him that seeth me?"}], [{"ref": "Genesis 16:15", "text": "And Hagar bare Abram a son: and Abram called his son’s name, which Hagar bare, Ishmael."}]]'::jsonb, updated_at = now() where id = 'who-hagar' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Esther 3:1", "text": "After these things did king Ahasuerus promote Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes that were with him."}], [{"ref": "Esther 3:5", "text": "And when Haman saw that Mordecai bowed not, nor did him reverence, then was Haman full of wrath."}], [{"ref": "Esther 3:6-7", "text": "And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai. In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar."}], [{"ref": "Esther 7:10", "text": "So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified."}]]'::jsonb, updated_at = now() where id = 'who-haman' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:1-2", "text": "Now there was a certain man of Ramathaim-zophim, of mount Ephraim, and his name was Elkanah, the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephrathite: And he had two wives; the name of the one was Hannah, and the name of the other Peninnah: and Peninnah had children, but Hannah had no children."}], [{"ref": "1 Samuel 1:9-13", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head. And it came to pass, as she continued praying before the LORD, that Eli marked her mouth. Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken."}], [{"ref": "1 Samuel 1:11", "text": "And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}], [{"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-hannah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 2:1", "text": "Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,"}], [{"ref": "Matthew 2:2-3", "text": "Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him. When Herod the king had heard these things, he was troubled, and all Jerusalem with him."}], [{"ref": "Matthew 2:8", "text": "And he sent them to Bethlehem, and said, Go and search diligently for the young child; and when ye have found him, bring me word again, that I may come and worship him also."}], [{"ref": "Matthew 2:16", "text": "Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men."}]]'::jsonb, updated_at = now() where id = 'who-herod' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 18:1", "text": "Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign."}], [{"ref": "2 Kings 18:4", "text": "He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan."}], [{"ref": "Isaiah 38:1", "text": "In those days was Hezekiah sick unto death. And Isaiah the prophet the son of Amoz came unto him, and said unto him, Thus saith the LORD, Set thine house in order: for thou shalt die, and not live."}], [{"ref": "Isaiah 38:5", "text": "Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years."}]]'::jsonb, updated_at = now() where id = 'who-hezekiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Hosea 1:1", "text": "The word of the LORD that came unto Hosea, the son of Beeri, in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah, and in the days of Jeroboam the son of Joash, king of Israel."}], [{"ref": "Hosea 1:3", "text": "So he went and took Gomer the daughter of Diblaim; which conceived, and bare him a son."}], [{"ref": "Hosea 1:8-9", "text": "Now when she had weaned Lo-ruhamah, she conceived, and bare a son. Then said God, Call his name Lo-ammi: for ye are not my people, and I will not be your God."}], [{"ref": "Hosea 3:2", "text": "So I bought her to me for fifteen pieces of silver, and for an homer of barley, and an half homer of barley:"}]]'::jsonb, updated_at = now() where id = 'who-hosea' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 21:5", "text": "And Abraham was an hundred years old, when his son Isaac was born unto him."}], [{"ref": "Genesis 22:2", "text": "And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}, {"ref": "Genesis 22:9", "text": "And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood."}], [{"ref": "Genesis 25:25-26", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau. And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}]]'::jsonb, updated_at = now() where id = 'who-isaac' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Isaiah 6:1", "text": "In the year that king Uzziah died I saw also the Lord sitting upon a throne, high and lifted up, and his train filled the temple."}], [{"ref": "Isaiah 6:6-7", "text": "Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar: And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged."}], [{"ref": "Isaiah 6:8", "text": "Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me."}], [{"ref": "Isaiah 7:14", "text": "Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel."}]]'::jsonb, updated_at = now() where id = 'who-isaiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 16:1", "text": "Now Sarai Abram’s wife bare him no children: and she had an handmaid, an Egyptian, whose name was Hagar."}], [{"ref": "Genesis 16:11", "text": "And the angel of the LORD said unto her, Behold, thou art with child, and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction."}], [{"ref": "Genesis 16:11", "text": "And the angel of the LORD said unto her, Behold, thou art with child, and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction."}], [{"ref": "Galatians 4:22-23", "text": "For it is written, that Abraham had two sons, the one by a bondmaid, the other by a freewoman. But he who was of the bondwoman was born after the flesh; but he of the freewoman was by promise."}]]'::jsonb, updated_at = now() where id = 'who-ishmael' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 25:26", "text": "And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 28:12", "text": "And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it."}], [{"ref": "Genesis 35:10", "text": "And God said unto him, Thy name is Jacob: thy name shall not be called any more Jacob, but Israel shall be thy name: and he called his name Israel."}]]'::jsonb, updated_at = now() where id = 'who-jacob' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:19", "text": "And he said unto her, Give me, I pray thee, a little water to drink; for I am thirsty. And she opened a bottle of milk, and gave him drink, and covered him."}], [{"ref": "Judges 4:21", "text": "Then Jael Heber’s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died."}]]'::jsonb, updated_at = now() where id = 'who-jael' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Mark 5:22", "text": "And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet,"}], [{"ref": "Luke 8:41", "text": "And, behold, there came a man named Jairus, and he was a ruler of the synagogue: and he fell down at Jesus’ feet, and besought him that he would come into his house:"}], [{"ref": "Mark 5:23", "text": "And besought him greatly, saying, My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live."}], [{"ref": "Mark 5:41", "text": "And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise."}]]'::jsonb, updated_at = now() where id = 'who-jairus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Mark 3:17", "text": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}], [{"ref": "Acts 12:1-2", "text": "Now about that time Herod the king stretched forth his hands to vex certain of the church. And he killed James the brother of John with the sword."}]]'::jsonb, updated_at = now() where id = 'who-james_zebedee' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 9:4-6", "text": "So the young man, even the young man the prophet, went to Ramoth-gilead. And when he came, behold, the captains of the host were sitting; and he said, I have an errand to thee, O captain. And Jehu said, Unto which of all us? And he said, To thee, O captain. And he arose, and went into the house; and he poured the oil on his head, and said unto him, Thus saith the LORD God of Israel, I have anointed thee king over the people of the LORD, even over Israel."}], [{"ref": "2 Kings 9:20", "text": "And the watchman told, saying, He came even unto them, and cometh not again: and the driving is like the driving of Jehu the son of Nimshi; for he driveth furiously."}], [{"ref": "2 Kings 9:30", "text": "And when Jehu was come to Jezreel, Jezebel heard of it; and she painted her face, and tired her head, and looked out at a window."}, {"ref": "2 Kings 9:33", "text": "And he said, Throw her down. So they threw her down: and some of her blood was sprinkled on the wall, and on the horses: and he trode her under foot."}], [{"ref": "2 Kings 10:28", "text": "Thus Jehu destroyed Baal out of Israel."}]]'::jsonb, updated_at = now() where id = 'who-jehu' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 11:1", "text": "Now Jephthah the Gileadite was a mighty man of valour, and he was the son of an harlot: and Gilead begat Jephthah."}], [{"ref": "Judges 11:2-3", "text": "And Gilead’s wife bare him sons; and his wife’s sons grew up, and they thrust out Jephthah, and said unto him, Thou shalt not inherit in our father’s house; for thou art the son of a strange woman. Then Jephthah fled from his brethren, and dwelt in the land of Tob: and there were gathered vain men to Jephthah, and went out with him."}], [{"ref": "Judges 11:30-31", "text": "And Jephthah vowed a vow unto the LORD, and said, If thou shalt without fail deliver the children of Ammon into mine hands, Then it shall be, that whatsoever cometh forth of the doors of my house to meet me, when I return in peace from the children of Ammon, shall surely be the LORD’s, and I will offer it up for a burnt offering."}], [{"ref": "Judges 11:34", "text": "And Jephthah came to Mizpeh unto his house, and, behold, his daughter came out to meet him with timbrels and with dances: and she was his only child; beside her he had neither son nor daughter."}]]'::jsonb, updated_at = now() where id = 'who-jephthah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Jeremiah 1:5", "text": "Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations."}], [{"ref": "Jeremiah 1:6", "text": "Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child."}], [{"ref": "Jeremiah 38:6", "text": "Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that was in the court of the prison: and they let down Jeremiah with cords. And in the dungeon there was no water, but mire: so Jeremiah sunk in the mire."}], [{"ref": "Jeremiah 36:4", "text": "Then Jeremiah called Baruch the son of Neriah: and Baruch wrote from the mouth of Jeremiah all the words of the LORD, which he had spoken unto him, upon a roll of a book."}]]'::jsonb, updated_at = now() where id = 'who-jeremiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 11:26", "text": "And Jeroboam the son of Nebat, an Ephrathite of Zereda, Solomon’s servant, whose mother’s name was Zeruah, a widow woman, even he lifted up his hand against the king."}], [{"ref": "1 Kings 11:29-31", "text": "And it came to pass at that time when Jeroboam went out of Jerusalem, that the prophet Ahijah the Shilonite found him in the way; and he had clad himself with a new garment; and they two were alone in the field: And Ahijah caught the new garment that was on him, and rent it in twelve pieces: And he said to Jeroboam, Take thee ten pieces: for thus saith the LORD, the God of Israel, Behold, I will rend the kingdom out of the hand of Solomon, and will give ten tribes to thee:"}], [{"ref": "1 Kings 12:20", "text": "And it came to pass, when all Israel heard that Jeroboam was come again, that they sent and called him unto the congregation, and made him king over all Israel: there was none that followed the house of David, but the tribe of Judah only."}], [{"ref": "1 Kings 12:28-29", "text": "Whereupon the king took counsel, and made two calves of gold, and said unto them, It is too much for you to go up to Jerusalem: behold thy gods, O Israel, which brought thee up out of the land of Egypt. And he set the one in Beth-el, and the other put he in Dan."}]]'::jsonb, updated_at = now() where id = 'who-jeroboam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:1", "text": "When Jethro, the priest of Midian, Moses’ father in law, heard of all that God had done for Moses, and for Israel his people, and that the LORD had brought Israel out of Egypt;"}], [{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:17-22", "text": "And Moses’ father in law said unto him, The thing that thou doest is not good. Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone. Hearken now unto my voice, I will give thee counsel, and God shall be with thee: Be thou for the people to God-ward, that thou mayest bring the causes unto God: And thou shalt teach them ordinances and laws, and shalt shew them the way wherein they must walk, and the work that they must do. Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and rulers of hundreds, rulers of fifties, and rulers of tens: And let them judge the people at all seasons: and it shall be, that every great matter they shall bring unto thee, but every small matter they shall judge: so shall it be easier for thyself, and they shall bear the burden with thee."}]]'::jsonb, updated_at = now() where id = 'who-jethro' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 19:1-2", "text": "And Ahab told Jezebel all that Elijah had done, and withal how he had slain all the prophets with the sword. Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time."}], [{"ref": "1 Kings 21:7-15", "text": "And Jezebel his wife said unto him, Dost thou now govern the kingdom of Israel? arise, and eat bread, and let thine heart be merry: I will give thee the vineyard of Naboth the Jezreelite. So she wrote letters in Ahab’s name, and sealed them with his seal, and sent the letters unto the elders and to the nobles that were in his city, dwelling with Naboth. And she wrote in the letters, saying, Proclaim a fast, and set Naboth on high among the people: And set two men, sons of Belial, before him, to bear witness against him, saying, Thou didst blaspheme God and the king. And then carry him out, and stone him, that he may die. And the men of his city, even the elders and the nobles who were the inhabitants in his city, did as Jezebel had sent unto them, and as it was written in the letters which she had sent unto them. They proclaimed a fast, and set Naboth on high among the people. And there came in two men, children of Belial, and sat before him: and the men of Belial witnessed against him, even against Naboth, in the presence of the people, saying, Naboth did blaspheme God and the king. Then they carried him forth out of the city, and stoned him with stones, that he died. Then they sent to Jezebel, saying, Naboth is stoned, and is dead. And it came to pass, when Jezebel heard that Naboth was stoned, and was dead, that Jezebel said to Ahab, Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give thee for money: for Naboth is not alive, but dead."}]]'::jsonb, updated_at = now() where id = 'who-jezebel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 8:16", "text": "And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud was recorder;"}], [{"ref": "2 Samuel 2:18", "text": "And there were three sons of Zeruiah there, Joab, and Abishai, and Asahel: and Asahel was as light of foot as a wild roe."}], [{"ref": "2 Samuel 3:27", "text": "And when Abner was returned to Hebron, Joab took him aside in the gate to speak with him quietly, and smote him there under the fifth rib, that he died, for the blood of Asahel his brother."}], [{"ref": "2 Samuel 18:14", "text": "Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak."}]]'::jsonb, updated_at = now() where id = 'who-joab' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:13-19", "text": "And there was a day when his sons and his daughters were eating and drinking wine in their eldest brother’s house: And there came a messenger unto Job, and said, The oxen were plowing, and the asses feeding beside them: And the Sabeans fell upon them, and took them away; yea, they have slain the servants with the edge of the sword; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The fire of God is fallen from heaven, and hath burned up the sheep, and the servants, and consumed them; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The Chaldeans made out three bands, and fell upon the camels, and have carried them away, yea, and slain the servants with the edge of the sword; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, Thy sons and thy daughters were eating and drinking wine in their eldest brother’s house: And, behold, there came a great wind from the wilderness, and smote the four corners of the house, and it fell upon the young men, and they are dead; and I only am escaped alone to tell thee."}], [{"ref": "Job 1:21", "text": "And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-job' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Mark 3:17", "text": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}], [{"ref": "John 21:20", "text": "Then Peter, turning about, seeth the disciple whom Jesus loved following; which also leaned on his breast at supper, and said, Lord, which is he that betrayeth thee?"}], [{"ref": "Revelation 1:9", "text": "I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ."}]]'::jsonb, updated_at = now() where id = 'who-john_apostle' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}, {"ref": "Luke 1:13", "text": "But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Mark 1:9", "text": "And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan."}]]'::jsonb, updated_at = now() where id = 'who-john_baptist' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 12:12", "text": "And when he had considered the thing, he came to the house of Mary the mother of John, whose surname was Mark; where many were gathered together praying."}], [{"ref": "Acts 12:25", "text": "And Barnabas and Saul returned from Jerusalem, when they had fulfilled their ministry, and took with them John, whose surname was Mark."}, {"ref": "Acts 13:13", "text": "Now when Paul and his company loosed from Paphos, they came to Perga in Pamphylia: and John departing from them returned to Jerusalem."}], [{"ref": "Acts 15:37-39", "text": "And Barnabas determined to take with them John, whose surname was Mark. But Paul thought not good to take him with them, who departed from them from Pamphylia, and went not with them to the work. And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus;"}], [{"ref": "2 Timothy 4:11", "text": "Only Luke is with me. Take Mark, and bring him with thee: for he is profitable to me for the ministry."}]]'::jsonb, updated_at = now() where id = 'who-john_mark' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 14:25", "text": "He restored the coast of Israel from the entering of Hamath unto the sea of the plain, according to the word of the LORD God of Israel, which he spake by the hand of his servant Jonah, the son of Amittai, the prophet, which was of Gath-hepher."}], [{"ref": "Jonah 1:3", "text": "But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD."}], [{"ref": "Jonah 1:17", "text": "Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights."}], [{"ref": "Jonah 3:10", "text": "And God saw their works, that they turned from their evil way; and God repented of the evil, that he had said that he would do unto them; and he did it not."}, {"ref": "Jonah 4:1", "text": "But it displeased Jonah exceedingly, and he was very angry."}]]'::jsonb, updated_at = now() where id = 'who-jonah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 14:1", "text": "Now it came to pass upon a day, that Jonathan the son of Saul said unto the young man that bare his armour, Come, and let us go over to the Philistines’ garrison, that is on the other side. But he told not his father."}], [{"ref": "1 Samuel 14:13", "text": "And Jonathan climbed up upon his hands and upon his feet, and his armourbearer after him: and they fell before Jonathan; and his armourbearer slew after him."}], [{"ref": "1 Samuel 18:1", "text": "And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul."}], [{"ref": "1 Samuel 20:20-22", "text": "And I will shoot three arrows on the side thereof, as though I shot at a mark. And, behold, I will send a lad, saying, Go, find out the arrows. If I expressly say unto the lad, Behold, the arrows are on this side of thee, take them; then come thou: for there is peace to thee, and no hurt; as the LORD liveth. But if I say thus unto the young man, Behold, the arrows are beyond thee; go thy way: for the LORD hath sent thee away."}, {"ref": "1 Samuel 20:36-37", "text": "And he said unto his lad, Run, find out now the arrows which I shoot. And as the lad ran, he shot an arrow beyond him. And when the lad was come to the place of the arrow which Jonathan had shot, Jonathan cried after the lad, and said, Is not the arrow beyond thee?"}]]'::jsonb, updated_at = now() where id = 'who-jonathan' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 37:3", "text": "Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."}], [{"ref": "Genesis 37:26-28", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content. Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt."}], [{"ref": "Genesis 41:25", "text": "And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do."}], [{"ref": "Genesis 41:41", "text": "And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt."}]]'::jsonb, updated_at = now() where id = 'who-joseph' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Mark 15:43", "text": "Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus."}], [{"ref": "John 19:38", "text": "And after this Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, besought Pilate that he might take away the body of Jesus: and Pilate gave him leave. He came therefore, and took the body of Jesus."}], [{"ref": "Mark 15:43", "text": "Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus."}], [{"ref": "Matthew 27:60", "text": "And laid it in his own new tomb, which he had hewn out in the rock: and he rolled a great stone to the door of the sepulchre, and departed."}]]'::jsonb, updated_at = now() where id = 'who-joseph_arimathea' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:4", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:)"}], [{"ref": "Matthew 1:20", "text": "But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost."}], [{"ref": "Matthew 2:14", "text": "When he arose, he took the young child and his mother by night, and departed into Egypt:"}], [{"ref": "Matthew 13:55", "text": "Is not this the carpenter’s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?"}]]'::jsonb, updated_at = now() where id = 'who-joseph_husband' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Numbers 13:2-16", "text": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them. And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel. And these were their names: of the tribe of Reuben, Shammua the son of Zaccur. Of the tribe of Simeon, Shaphat the son of Hori. Of the tribe of Judah, Caleb the son of Jephunneh. Of the tribe of Issachar, Igal the son of Joseph. Of the tribe of Ephraim, Oshea the son of Nun. Of the tribe of Benjamin, Palti the son of Raphu. Of the tribe of Zebulun, Gaddiel the son of Sodi. Of the tribe of Joseph, namely, of the tribe of Manasseh, Gaddi the son of Susi. Of the tribe of Dan, Ammiel the son of Gemalli. Of the tribe of Asher, Sethur the son of Michael. Of the tribe of Naphtali, Nahbi the son of Vophsi. Of the tribe of Gad, Geuel the son of Machi. These are the names of the men which Moses sent to spy out the land. And Moses called Oshea the son of Nun Jehoshua."}], [{"ref": "Joshua 1:1-2", "text": "Now after the death of Moses the servant of the LORD it came to pass, that the LORD spake unto Joshua the son of Nun, Moses’ minister, saying, Moses my servant is dead; now therefore arise, go over this Jordan, thou, and all this people, unto the land which I do give to them, even to the children of Israel."}], [{"ref": "Joshua 6:16", "text": "And it came to pass at the seventh time, when the priests blew with the trumpets, Joshua said unto the people, Shout; for the LORD hath given you the city."}, {"ref": "Joshua 6:20", "text": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}], [{"ref": "Joshua 24:15", "text": "And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."}]]'::jsonb, updated_at = now() where id = 'who-joshua' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 22:1", "text": "Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath."}], [{"ref": "2 Kings 22:8", "text": "And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it."}], [{"ref": "2 Kings 22:11", "text": "And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes."}], [{"ref": "2 Kings 23:21-23", "text": "And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant. Surely there was not holden such a passover from the days of the judges that judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah; But in the eighteenth year of king Josiah, wherein this passover was holden to the LORD in Jerusalem."}]]'::jsonb, updated_at = now() where id = 'who-josiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 29:32-35", "text": "And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the LORD hath looked upon my affliction; now therefore my husband will love me. And she conceived again, and bare a son; and said, Because the LORD hath heard that I was hated, he hath therefore given me this son also: and she called his name Simeon. And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi. And she conceived again, and bare a son: and she said, Now will I praise the LORD: therefore she called his name Judah; and left bearing."}], [{"ref": "Genesis 37:26-27", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content."}], [{"ref": "Genesis 44:18", "text": "Then Judah came near unto him, and said, Oh my lord, let thy servant, I pray thee, speak a word in my lord’s ears, and let not thine anger burn against thy servant: for thou art even as Pharaoh."}, {"ref": "Genesis 44:33", "text": "Now therefore, I pray thee, let thy servant abide instead of the lad a bondman to my lord; and let the lad go up with his brethren."}], [{"ref": "Genesis 49:10", "text": "The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be."}]]'::jsonb, updated_at = now() where id = 'who-judah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 26:14", "text": "Then one of the twelve, called Judas Iscariot, went unto the chief priests,"}], [{"ref": "John 12:4-6", "text": "Then saith one of his disciples, Judas Iscariot, Simon’s son, which should betray him, Why was not this ointment sold for three hundred pence, and given to the poor? This he said, not that he cared for the poor; but because he was a thief, and had the bag, and bare what was put therein."}], [{"ref": "Matthew 26:15", "text": "And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver."}], [{"ref": "Matthew 26:48-49", "text": "Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast. And forthwith he came to Jesus, and said, Hail, master; and kissed him."}]]'::jsonb, updated_at = now() where id = 'who-judas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 29:10", "text": "And it came to pass, when Jacob saw Rachel the daughter of Laban his mother’s brother, and the sheep of Laban his mother’s brother, that Jacob went near, and rolled the stone from the well’s mouth, and watered the flock of Laban his mother’s brother."}, {"ref": "Genesis 29:18", "text": "And Jacob loved Rachel; and said, I will serve thee seven years for Rachel thy younger daughter."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}, {"ref": "Genesis 29:22-23", "text": "And Laban gathered together all the men of the place, and made a feast. And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}]]'::jsonb, updated_at = now() where id = 'who-laban' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:1", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha."}], [{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "John 11:34-35", "text": "And said, Where have ye laid him? They said unto him, Lord, come and see. Jesus wept."}, {"ref": "John 11:38", "text": "Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it."}], [{"ref": "John 11:43-44", "text": "And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go."}]]'::jsonb, updated_at = now() where id = 'who-lazarus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 29:17", "text": "Leah was tender eyed; but Rachel was beautiful and well favoured."}], [{"ref": "Genesis 29:23-26", "text": "And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her. And Laban gave unto his daughter Leah Zilpah his maid for an handmaid. And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me? And Laban said, It must not be so done in our country, to give the younger before the firstborn."}], [{"ref": "Genesis 29:32-35", "text": "And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the LORD hath looked upon my affliction; now therefore my husband will love me. And she conceived again, and bare a son; and said, Because the LORD hath heard that I was hated, he hath therefore given me this son also: and she called his name Simeon. And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi. And she conceived again, and bare a son: and she said, Now will I praise the LORD: therefore she called his name Judah; and left bearing."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}]]'::jsonb, updated_at = now() where id = 'who-leah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 12:5", "text": "And Abram took Sarai his wife, and Lot his brother’s son, and all their substance that they had gathered, and the souls that they had gotten in Haran; and they went forth to go into the land of Canaan; and into the land of Canaan they came."}], [{"ref": "Genesis 13:11", "text": "Then Lot chose him all the plain of Jordan; and Lot journeyed east: and they separated themselves the one from the other."}], [{"ref": "Genesis 19:1-3", "text": "And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground; And he said, Behold now, my lords, turn in, I pray you, into your servant’s house, and tarry all night, and wash your feet, and ye shall rise up early, and go on your ways. And they said, Nay; but we will abide in the street all night. And he pressed upon them greatly; and they turned in unto him, and entered into his house; and he made them a feast, and did bake unleavened bread, and they did eat."}], [{"ref": "Genesis 19:26", "text": "But his wife looked back from behind him, and she became a pillar of salt."}]]'::jsonb, updated_at = now() where id = 'who-lot' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:12-14", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days. And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither. And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:15", "text": "And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us."}]]'::jsonb, updated_at = now() where id = 'who-lydia' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "Luke 10:40", "text": "But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me."}], [{"ref": "Luke 10:42", "text": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}], [{"ref": "Luke 10:38", "text": "Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house."}]]'::jsonb, updated_at = now() where id = 'who-martha' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:27", "text": "To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 2:4-7", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:) To be taxed with Mary his espoused wife, being great with child. And so it was, that, while they were there, the days were accomplished that she should be delivered. And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."}, {"ref": "Luke 2:21", "text": "And when eight days were accomplished for the circumcising of the child, his name was called JESUS, which was so named of the angel before he was conceived in the womb."}]]'::jsonb, updated_at = now() where id = 'who-mary' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "Luke 10:39", "text": "And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word."}], [{"ref": "Luke 10:42", "text": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}], [{"ref": "John 12:3", "text": "Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment."}]]'::jsonb, updated_at = now() where id = 'who-mary_bethany' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 8:2", "text": "And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,"}], [{"ref": "John 19:25", "text": "Now there stood by the cross of Jesus his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene."}], [{"ref": "John 20:1", "text": "The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre."}], [{"ref": "John 20:15", "text": "Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away."}]]'::jsonb, updated_at = now() where id = 'who-mary_magdalene' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 10:3", "text": "Philip, and Bartholomew; Thomas, and Matthew the publican; James the son of Alphaeus, and Lebbaeus, whose surname was Thaddaeus;"}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9-10", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him. And it came to pass, as Jesus sat at meat in the house, behold, many publicans and sinners came and sat down with him and his disciples."}]]'::jsonb, updated_at = now() where id = 'who-matthew' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 1:21-23", "text": "Wherefore of these men which have companied with us all the time that the Lord Jesus went in and out among us, Beginning from the baptism of John, unto that same day that he was taken up from us, must one be ordained to be a witness with us of his resurrection. And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias."}], [{"ref": "Acts 1:23", "text": "And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias."}], [{"ref": "Acts 1:24-26", "text": "And they prayed, and said, Thou, Lord, which knowest the hearts of all men, shew whether of these two thou hast chosen, That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place. And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles."}], [{"ref": "Acts 1:25-26", "text": "That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place. And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles."}]]'::jsonb, updated_at = now() where id = 'who-matthias' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:17-18", "text": "And the king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer, and of the kings that were with him, at the valley of Shaveh, which is the king’s dale. And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Hebrews 7:2", "text": "To whom also Abraham gave a tenth part of all; first being by interpretation King of righteousness, and after that also King of Salem, which is, King of peace;"}]]'::jsonb, updated_at = now() where id = 'who-melchizedek' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 4:4", "text": "And Jonathan, Saul’s son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth."}], [{"ref": "2 Samuel 4:4", "text": "And Jonathan, Saul’s son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth."}], [{"ref": "2 Samuel 9:7", "text": "And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy father’s sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually."}, {"ref": "2 Samuel 9:9", "text": "Then the king called to Ziba, Saul’s servant, and said unto him, I have given unto thy master’s son all that pertained to Saul and to all his house."}], [{"ref": "2 Samuel 9:13", "text": "So Mephibosheth dwelt in Jerusalem: for he did eat continually at the king’s table; and was lame on both his feet."}]]'::jsonb, updated_at = now() where id = 'who-mephibosheth' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}, {"ref": "Genesis 5:28-29", "text": "And Lamech lived an hundred eighty and two years, and begat a son: And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which the LORD hath cursed."}], [{"ref": "Genesis 5:27", "text": "And all the days of Methuselah were nine hundred sixty and nine years: and he died."}]]'::jsonb, updated_at = now() where id = 'who-methuselah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 2:3-4", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink. And his sister stood afar off, to wit what would be done to him."}, {"ref": "Numbers 26:59", "text": "And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Numbers 12:10", "text": "And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."}, {"ref": "Numbers 12:14-15", "text": "And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again. And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again."}]]'::jsonb, updated_at = now() where id = 'who-miriam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Esther 2:5", "text": "Now in Shushan the palace there was a certain Jew, whose name was Mordecai, the son of Jair, the son of Shimei, the son of Kish, a Benjamite;"}, {"ref": "Esther 2:21", "text": "In those days, while Mordecai sat in the king’s gate, two of the king’s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hand on the king Ahasuerus."}], [{"ref": "Esther 2:21-22", "text": "In those days, while Mordecai sat in the king’s gate, two of the king’s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hand on the king Ahasuerus. And the thing was known to Mordecai, who told it unto Esther the queen; and Esther certified the king thereof in Mordecai’s name."}], [{"ref": "Esther 3:2", "text": "And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence."}], [{"ref": "Esther 2:7", "text": "And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}]]'::jsonb, updated_at = now() where id = 'who-mordecai' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 2:3", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."}], [{"ref": "Exodus 2:10", "text": "And the child grew, and she brought him unto Pharaoh’s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water."}], [{"ref": "Exodus 3:2", "text": "And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed."}], [{"ref": "Acts 7:36", "text": "He brought them out, after that he had shewed wonders and signs in the land of Egypt, and in the Red sea, and in the wilderness forty years."}]]'::jsonb, updated_at = now() where id = 'who-moses' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:2-3", "text": "And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naaman’s wife. And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy."}], [{"ref": "2 Kings 5:14", "text": "Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."}]]'::jsonb, updated_at = now() where id = 'who-naaman' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ruth 1:1-2", "text": "Now it came to pass in the days when the judges ruled, that there was a famine in the land. And a certain man of Beth-lehem-judah went to sojourn in the country of Moab, he, and his wife, and his two sons. And the name of the man was Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Beth-lehem-judah. And they came into the country of Moab, and continued there."}], [{"ref": "Ruth 1:3-5", "text": "And Elimelech Naomi’s husband died; and she was left, and her two sons. And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years. And Mahlon and Chilion died also both of them; and the woman was left of her two sons and her husband."}], [{"ref": "Ruth 1:20", "text": "And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me."}], [{"ref": "Ruth 1:16", "text": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}]]'::jsonb, updated_at = now() where id = 'who-naomi' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 7:2", "text": "That the king said unto Nathan the prophet, See now, I dwell in an house of cedar, but the ark of God dwelleth within curtains."}], [{"ref": "2 Samuel 7:4-5", "text": "And it came to pass that night, that the word of the LORD came unto Nathan, saying, Go and tell my servant David, Thus saith the LORD, Shalt thou build me an house for me to dwell in?"}, {"ref": "2 Samuel 7:12-13", "text": "And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom. He shall build an house for my name, and I will stablish the throne of his kingdom for ever."}], [{"ref": "2 Samuel 12:1-4", "text": "And the LORD sent Nathan unto David. And he came unto him, and said unto him, There were two men in one city; the one rich, and the other poor. The rich man had exceeding many flocks and herds: But the poor man had nothing, save one little ewe lamb, which he had bought and nourished up: and it grew up together with him, and with his children; it did eat of his own meat, and drank of his own cup, and lay in his bosom, and was unto him as a daughter. And there came a traveller unto the rich man, and he spared to take of his own flock and of his own herd, to dress for the wayfaring man that was come unto him; but took the poor man’s lamb, and dressed it for the man that was come to him."}], [{"ref": "2 Samuel 12:7", "text": "And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;"}]]'::jsonb, updated_at = now() where id = 'who-nathan' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 21:2", "text": "There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the sons of Zebedee, and two other of his disciples."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 1:48", "text": "Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee."}], [{"ref": "John 1:47", "text": "Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!"}]]'::jsonb, updated_at = now() where id = 'who-nathanael' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Daniel 1:1", "text": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it."}], [{"ref": "Daniel 2:1", "text": "And in the second year of the reign of Nebuchadnezzar Nebuchadnezzar dreamed dreams, wherewith his spirit was troubled, and his sleep brake from him."}, {"ref": "Daniel 2:31-32", "text": "Thou, O king, sawest, and behold a great image. This great image, whose brightness was excellent, stood before thee; and the form thereof was terrible. This image’s head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"}], [{"ref": "Daniel 3:1", "text": "Nebuchadnezzar the king made an image of gold, whose height was threescore cubits, and the breadth thereof six cubits: he set it up in the plain of Dura, in the province of Babylon."}, {"ref": "Daniel 3:4-5", "text": "Then an herald cried aloud, To you it is commanded, O people, nations, and languages, That at what time ye hear the sound of the cornet, flute, harp, sackbut, psaltery, dulcimer, and all kinds of musick, ye fall down and worship the golden image that Nebuchadnezzar the king hath set up:"}], [{"ref": "Daniel 4:32-33", "text": "And they shall drive thee from men, and thy dwelling shall be with the beasts of the field: they shall make thee to eat grass as oxen, and seven times shall pass over thee, until thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will. The same hour was the thing fulfilled upon Nebuchadnezzar: and he was driven from men, and did eat grass as oxen, and his body was wet with the dew of heaven, till his hairs were grown like eagles’ feathers, and his nails like birds’ claws."}]]'::jsonb, updated_at = now() where id = 'who-nebuchadnezzar' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Nehemiah 1:11", "text": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."}, {"ref": "Nehemiah 2:1", "text": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}], [{"ref": "Nehemiah 1:3-4", "text": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire. And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}], [{"ref": "Nehemiah 2:17-18", "text": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach. Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work."}], [{"ref": "Nehemiah 6:15", "text": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}]]'::jsonb, updated_at = now() where id = 'who-nehemiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 3:1", "text": "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"}], [{"ref": "John 3:2", "text": "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."}], [{"ref": "John 3:7", "text": "Marvel not that I said unto thee, Ye must be born again."}], [{"ref": "John 19:39", "text": "And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight."}]]'::jsonb, updated_at = now() where id = 'who-nicodemus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 7:6", "text": "And Noah was six hundred years old when the flood of waters was upon the earth."}], [{"ref": "Genesis 6:14", "text": "Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."}], [{"ref": "Genesis 6:10", "text": "And Noah begat three sons, Shem, Ham, and Japheth."}], [{"ref": "Hebrews 11:7", "text": "By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith."}]]'::jsonb, updated_at = now() where id = 'who-noah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Philemon 1:15", "text": "For perhaps he therefore departed for a season, that thou shouldest receive him for ever;"}], [{"ref": "Philemon 1:10", "text": "I beseech thee for my son Onesimus, whom I have begotten in my bonds:"}], [{"ref": "Philemon 1:11", "text": "Which in time past was to thee unprofitable, but now profitable to thee and to me:"}], [{"ref": "Philemon 1:12-16", "text": "Whom I have sent again: thou therefore receive him, that is, mine own bowels: Whom I would have retained with me, that in thy stead he might have ministered unto me in the bonds of the gospel: But without thy mind would I do nothing; that thy benefit should not be as it were of necessity, but willingly. For perhaps he therefore departed for a season, that thou shouldest receive him for ever; Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord?"}]]'::jsonb, updated_at = now() where id = 'who-onesimus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}], [{"ref": "Galatians 1:13", "text": "For ye have heard of my conversation in time past in the Jews’ religion, how that beyond measure I persecuted the church of God, and wasted it:"}], [{"ref": "Acts 9:3-8", "text": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks. And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do. And the men which journeyed with him stood speechless, hearing a voice, but seeing no man. And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him by the hand, and brought him into Damascus."}, {"ref": "Acts 22:11", "text": "And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus."}], [{"ref": "2 Peter 3:15-16", "text": "And account that the longsuffering of our Lord is salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you; As also in all his epistles, speaking in them of these things; in which are some things hard to be understood, which they that are unlearned and unstable wrest, as they do also the other scriptures, unto their own destruction."}]]'::jsonb, updated_at = now() where id = 'who-paul' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 4:18", "text": "And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers."}], [{"ref": "Matthew 4:19", "text": "And he saith unto them, Follow me, and I will make you fishers of men."}], [{"ref": "Matthew 14:29", "text": "And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus."}], [{"ref": "Matthew 26:75", "text": "And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly."}]]'::jsonb, updated_at = now() where id = 'who-peter' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:43", "text": "The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 14:8", "text": "Philip saith unto him, Lord, shew us the Father, and it sufficeth us."}]]'::jsonb, updated_at = now() where id = 'who-philip_apostle' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 3:1", "text": "Now in the fifteenth year of the reign of Tiberius Cæsar, Pontius Pilate being governor of Judæa, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,"}], [{"ref": "Matthew 27:19", "text": "When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him."}], [{"ref": "John 18:38", "text": "Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault at all."}], [{"ref": "Matthew 27:24", "text": "When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it."}]]'::jsonb, updated_at = now() where id = 'who-pilate' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 18:3", "text": "And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:2", "text": "And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them."}], [{"ref": "Acts 18:1-3", "text": "After these things Paul departed from Athens, and came to Corinth; And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them. And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}]]'::jsonb, updated_at = now() where id = 'who-priscilla' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}], [{"ref": "Genesis 29:20", "text": "And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her."}], [{"ref": "Genesis 35:24", "text": "The sons of Rachel; Joseph, and Benjamin:"}], [{"ref": "Genesis 35:19", "text": "And Rachel died, and was buried in the way to Ephrath, which is Beth-lehem."}]]'::jsonb, updated_at = now() where id = 'who-rachel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:4", "text": "And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were:"}], [{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:17-21", "text": "And the men said unto her, We will be blameless of this thine oath which thou hast made us swear. Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father’s household, home unto thee. And it shall be, that whosoever shall go out of the doors of thy house into the street, his blood shall be upon his head, and we will be guiltless: and whosoever shall be with thee in the house, his blood shall be on our head, if any hand be upon him. And if thou utter this our business, then we will be quit of thine oath which thou hast made us to swear. And she said, According unto your words, so be it. And she sent them away, and they departed: and she bound the scarlet line in the window."}]]'::jsonb, updated_at = now() where id = 'who-rahab' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 24:19-20", "text": "And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking. And she hasted, and emptied her pitcher into the trough, and ran again unto the well to draw water, and drew for all his camels."}], [{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 24:67", "text": "And Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother’s death."}], [{"ref": "Genesis 27:6-17", "text": "And Rebekah spake unto Jacob her son, saying, Behold, I heard thy father speak unto Esau thy brother, saying, Bring me venison, and make me savoury meat, that I may eat, and bless thee before the LORD before my death. Now therefore, my son, obey my voice according to that which I command thee. Go now to the flock, and fetch me from thence two good kids of the goats; and I will make them savoury meat for thy father, such as he loveth: And thou shalt bring it to thy father, that he may eat, and that he may bless thee before his death. And Jacob said to Rebekah his mother, Behold, Esau my brother is a hairy man, and I am a smooth man: My father peradventure will feel me, and I shall seem to him as a deceiver; and I shall bring a curse upon me, and not a blessing. And his mother said unto him, Upon me be thy curse, my son: only obey my voice, and go fetch me them. And he went, and fetched, and brought them to his mother: and his mother made savoury meat, such as his father loved. And Rebekah took goodly raiment of her eldest son Esau, which were with her in the house, and put them upon Jacob her younger son: And she put the skins of the kids of the goats upon his hands, and upon the smooth of his neck: And she gave the savoury meat and the bread, which she had prepared, into the hand of her son Jacob."}]]'::jsonb, updated_at = now() where id = 'who-rebekah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 11:43", "text": "And Solomon slept with his fathers, and was buried in the city of David his father: and Rehoboam his son reigned in his stead."}], [{"ref": "1 Kings 12:8", "text": "But he forsook the counsel of the old men, which they had given him, and consulted with the young men that were grown up with him, and which stood before him:"}], [{"ref": "1 Kings 12:14", "text": "And spake to them after the counsel of the young men, saying, My father made your yoke heavy, and I will add to your yoke: my father also chastised you with whips, but I will chastise you with scorpions."}], [{"ref": "1 Kings 11:31", "text": "And he said to Jeroboam, Take thee ten pieces: for thus saith the LORD, the God of Israel, Behold, I will rend the kingdom out of the hand of Solomon, and will give ten tribes to thee:"}, {"ref": "1 Kings 12:16", "text": "So when all Israel saw that the king hearkened not unto them, the people answered the king, saying, What portion have we in David? neither have we inheritance in the son of Jesse: to your tents, O Israel: now see to thine own house, David. So Israel departed unto their tents."}, {"ref": "1 Kings 12:19", "text": "So Israel rebelled against the house of David unto this day."}]]'::jsonb, updated_at = now() where id = 'who-rehoboam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 35:23", "text": "The sons of Leah; Reuben, Jacob’s firstborn, and Simeon, and Levi, and Judah, and Issachar, and Zebulun:"}], [{"ref": "Genesis 30:14", "text": "And Reuben went in the days of wheat harvest, and found mandrakes in the field, and brought them unto his mother Leah. Then Rachel said to Leah, Give me, I pray thee, of thy son’s mandrakes."}], [{"ref": "Genesis 37:21-22", "text": "And Reuben heard it, and he delivered him out of their hands; and said, Let us not kill him. And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again."}], [{"ref": "Genesis 37:22", "text": "And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again."}]]'::jsonb, updated_at = now() where id = 'who-reuben' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ruth 1:4", "text": "And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years."}], [{"ref": "Ruth 1:16", "text": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}], [{"ref": "Ruth 2:3", "text": "And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech."}], [{"ref": "Ruth 4:13-17", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son. And the women said unto Naomi, Blessed be the LORD, which hath not left thee this day without a kinsman, that his name may be famous in Israel. And he shall be unto thee a restorer of thy life, and a nourisher of thine old age: for thy daughter in law, which loveth thee, which is better to thee than seven sons, hath born him. And Naomi took the child, and laid it in her bosom, and became nurse unto it. And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."}]]'::jsonb, updated_at = now() where id = 'who-ruth' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 16:17", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man."}], [{"ref": "Judges 14:5-6", "text": "Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him. And the Spirit of the LORD came mightily upon him, and he rent him as he would have rent a kid, and he had nothing in his hand: but he told not his father or his mother what he had done."}], [{"ref": "Judges 16:17-18", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man. And when Delilah saw that he had told her all his heart, she sent and called for the lords of the Philistines, saying, Come up this once, for he hath shewed me all his heart. Then the lords of the Philistines came up unto her, and brought money in their hand."}], [{"ref": "Judges 16:29-30", "text": "And Samson took hold of the two middle pillars upon which the house stood, and on which it was borne up, of the one with his right hand, and of the other with his left. And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life."}]]'::jsonb, updated_at = now() where id = 'who-samson' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9-11", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}, {"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}], [{"ref": "1 Samuel 2:11", "text": "And Elkanah went to Ramah to his house. And the child did minister unto the LORD before Eli the priest."}, {"ref": "1 Samuel 3:1", "text": "And the child Samuel ministered unto the LORD before Eli. And the word of the LORD was precious in those days; there was no open vision."}], [{"ref": "1 Samuel 3:10", "text": "And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth."}], [{"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}, {"ref": "1 Samuel 16:13", "text": "Then Samuel took the horn of oil, and anointed him in the midst of his brethren: and the Spirit of the LORD came upon David from that day forward. So Samuel rose up, and went to Ramah."}]]'::jsonb, updated_at = now() where id = 'who-samuel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 9:21", "text": "And Saul answered and said, Am not I a Benjamite, of the smallest of the tribes of Israel? and my family the least of all the families of the tribe of Benjamin? wherefore then speakest thou so to me?"}], [{"ref": "1 Samuel 9:2", "text": "And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people."}], [{"ref": "1 Samuel 9:17", "text": "And when Samuel saw Saul, the LORD said unto him, Behold the man whom I spake to thee of! this same shall reign over my people."}, {"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}], [{"ref": "1 Samuel 28:7-8", "text": "Then said Saul unto his servants, Seek me a woman that hath a familiar spirit, that I may go to her, and enquire of her. And his servants said to him, Behold, there is a woman that hath a familiar spirit at Endor. And Saul disguised himself, and put on other raiment, and he went, and two men with him, and they came to the woman by night: and he said, I pray thee, divine unto me by the familiar spirit, and bring me him up, whom I shall name unto thee."}]]'::jsonb, updated_at = now() where id = 'who-saul' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 15:22", "text": "Then pleased it the apostles and elders, with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas; namely, Judas surnamed Barsabas, and Silas, chief men among the brethren:"}], [{"ref": "Acts 15:39-40", "text": "And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus; And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God."}], [{"ref": "Acts 16:12", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days."}, {"ref": "Acts 16:19", "text": "And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers,"}, {"ref": "Acts 16:22-25", "text": "And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them. And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely: Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks. And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}], [{"ref": "Acts 16:25", "text": "And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}]]'::jsonb, updated_at = now() where id = 'who-silas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:25", "text": "And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him."}], [{"ref": "Luke 2:26", "text": "And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord’s Christ."}], [{"ref": "Luke 2:27-28", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law, Then took he him up in his arms, and blessed God, and said,"}], [{"ref": "Luke 2:29", "text": "Lord, now lettest thou thy servant depart in peace, according to thy word:"}]]'::jsonb, updated_at = now() where id = 'who-simeon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Mark 15:21", "text": "And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."}], [{"ref": "Matthew 27:32", "text": "And as they came out, they found a man of Cyrene, Simon by name: him they compelled to bear his cross."}], [{"ref": "Luke 23:26", "text": "And as they led him away, they laid hold upon one Simon, a Cyrenian, coming out of the country, and on him they laid the cross, that he might bear it after Jesus."}], [{"ref": "Mark 15:21", "text": "And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."}]]'::jsonb, updated_at = now() where id = 'who-simon_cyrene' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 3:9", "text": "Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?"}], [{"ref": "1 Kings 6:14", "text": "So Solomon built the house, and finished it."}], [{"ref": "1 Kings 3:16-27", "text": "Then came there two women, that were harlots, unto the king, and stood before him. And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house. And it came to pass the third day after that I was delivered, that this woman was delivered also: and we were together; there was no stranger with us in the house, save we two in the house. And this woman’s child died in the night; because she overlaid it. And she arose at midnight, and took my son from beside me, while thine handmaid slept, and laid it in her bosom, and laid her dead child in my bosom. And when I rose in the morning to give my child suck, behold, it was dead: but when I had considered it in the morning, behold, it was not my son, which I did bear. And the other woman said, Nay; but the living is my son, and the dead is thy son. And this said, No; but the dead is thy son, and the living is my son. Thus they spake before the king. Then said the king, The one saith, This is my son that liveth, and thy son is the dead: and the other saith, Nay; but thy son is the dead, and my son is the living. And the king said, Bring me a sword. And they brought a sword before the king. And the king said, Divide the living child in two, and give half to the one, and half to the other. Then spake the woman whose the living child was unto the king, for her bowels yearned upon her son, and she said, O my lord, give her the living child, and in no wise slay it. But the other said, Let it be neither mine nor thine, but divide it. Then the king answered and said, Give her the living child, and in no wise slay it: she is the mother thereof."}]]'::jsonb, updated_at = now() where id = 'who-solomon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 6:2-5", "text": "Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables. Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business. But we will give ourselves continually to prayer, and to the ministry of the word. And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:"}], [{"ref": "Acts 6:8", "text": "And Stephen, full of faith and power, did great wonders and miracles among the people."}], [{"ref": "Acts 7:56", "text": "And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God."}], [{"ref": "Acts 7:58", "text": "And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul."}]]'::jsonb, updated_at = now() where id = 'who-stephen' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:19", "text": "Then the same day at evening, being the first day of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace be unto you."}, {"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:25", "text": "The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe."}], [{"ref": "John 20:28", "text": "And Thomas answered and said unto him, My Lord and my God."}]]'::jsonb, updated_at = now() where id = 'who-thomas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Timothy 1:5", "text": "When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also."}], [{"ref": "Acts 16:1-3", "text": "Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek: Which was well reported of by the brethren that were at Lystra and Iconium. Him would Paul have to go forth with him; and took and circumcised him because of the Jews which were in those quarters: for they knew all that his father was a Greek."}, {"ref": "1 Timothy 4:12", "text": "Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity."}], [{"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}], [{"ref": "1 Timothy 1:2", "text": "Unto Timothy, my own son in the faith: Grace, mercy, and peace, from God our Father and Jesus Christ our Lord."}, {"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}]]'::jsonb, updated_at = now() where id = 'who-timothy' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}, {"ref": "2 Samuel 23:8", "text": "These be the names of the mighty men whom David had: The Tachmonite that sat in the seat, chief among the captains; the same was Adino the Eznite: he lift up his spear against eight hundred, whom he slew at one time."}, {"ref": "2 Samuel 23:39", "text": "Uriah the Hittite: thirty and seven in all."}], [{"ref": "2 Samuel 11:11", "text": "And Uriah said unto David, The ark, and Israel, and Judah, abide in tents; and my lord Joab, and the servants of my lord, are encamped in the open fields; shall I then go into mine house, to eat and to drink, and to lie with my wife? as thou livest, and as thy soul liveth, I will not do this thing."}], [{"ref": "2 Samuel 11:14-15", "text": "And it came to pass in the morning, that David wrote a letter to Joab, and sent it by the hand of Uriah. And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die."}], [{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}]]'::jsonb, updated_at = now() where id = 'who-uriah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Esther 1:9", "text": "Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus."}], [{"ref": "Esther 1:9", "text": "Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus."}], [{"ref": "Esther 1:12", "text": "But the queen Vashti refused to come at the king’s commandment by his chamberlains: therefore was the king very wroth, and his anger burned in him."}], [{"ref": "Esther 1:19", "text": "If it please the king, let there go a royal commandment from him, and let it be written among the laws of the Persians and the Medes, that it be not altered, That Vashti come no more before king Ahasuerus; and let the king give her royal estate unto another that is better than she."}, {"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}]]'::jsonb, updated_at = now() where id = 'who-vashti' and game_mode = 'whoami';
